WITH payload AS (
  SELECT * FROM jsonb_to_recordset('[{"MATERIA":"BIOLOGIA CELULAR","TEMA":"transcripcion y maduracion del arn","DIFICULTAD":"facil","PREGUNTA":"¿Qué ARN polimerasa eucariota transcribe la mayoría de los genes de ARN mensajero?","OPCION_A":"La ARN polimerasa II.","OPCION_B":"El ARN ribosómico 18 S.","OPCION_C":"El espliceosoma.","OPCION_D":"El ARN de transferencia.","RESPUESTA_CORRECTA":"A","EXPLICACION":"La ARN polimerasa II.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"351–381"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"transcripcion y maduracion del arn","DIFICULTAD":"facil","PREGUNTA":"¿Qué ARN polimerasa fabrica el precursor principal de los ARN ribosómicos en el nucléolo?","OPCION_A":"La ARN polimerasa I.","OPCION_B":"Los ARN ribosómicos 18 S, 5.8 S y 28 S.","OPCION_C":"El ARN ribosómico.","OPCION_D":"El ARN mensajero.","RESPUESTA_CORRECTA":"A","EXPLICACION":"La ARN polimerasa I.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"351–381"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"transcripcion y maduracion del arn","DIFICULTAD":"facil","PREGUNTA":"¿Qué ARN polimerasa transcribe los genes de ARN de transferencia y el ARN ribosómico 5 S?","OPCION_A":"El ARN ribosómico 18 S.","OPCION_B":"El ARN de transferencia.","OPCION_C":"La ARN polimerasa III.","OPCION_D":"El ARN mensajero.","RESPUESTA_CORRECTA":"C","EXPLICACION":"La ARN polimerasa III.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"351–381"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"transcripcion y maduracion del arn","DIFICULTAD":"medio","PREGUNTA":"Si la cromatina está muy compactada, ¿qué dificultad encuentra la transcripción?","OPCION_A":"Los factores y la ARN polimerasa acceden con más dificultad al ADN.","OPCION_B":"El ARN lleva uracilo donde la hebra codificante de ADN tiene timina.","OPCION_C":"El procesamiento o la exportación del ARN hacia el citoplasma.","OPCION_D":"El ADN sirve de molde, pero no se consume ni se convierte en ARN.","RESPUESTA_CORRECTA":"A","EXPLICACION":"Los factores y la ARN polimerasa acceden con más dificultad al ADN.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"351–381"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"transcripcion y maduracion del arn","DIFICULTAD":"facil","PREGUNTA":"¿Qué hacen los complejos que remodelan la cromatina?","OPCION_A":"Reconocen secuencias del ADN y ayudan a reclutar o regular la ARN polimerasa.","OPCION_B":"Elegir combinaciones distintas de exones de un mismo transcrito.","OPCION_C":"Suele volverse menos estable y más susceptible a degradación.","OPCION_D":"Mueven o reorganizan nucleosomas para cambiar el acceso al ADN.","RESPUESTA_CORRECTA":"D","EXPLICACION":"Mueven o reorganizan nucleosomas para cambiar el acceso al ADN.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"351–381"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"transcripcion y maduracion del arn","DIFICULTAD":"dificil","PREGUNTA":"¿Por qué la acetilación de histonas suele favorecer un gen activo?","OPCION_A":"Pueden diferir en transcripción, procesamiento, estabilidad o traducción del ARN.","OPCION_B":"Su actividad se regula según el tipo de célula, las señales y las necesidades del momento.","OPCION_C":"Tiende a abrir la cromatina y facilita que la maquinaria de transcripción acceda al ADN.","OPCION_D":"Puede cambiar qué exones quedan en el ARN maduro y, con ello, la secuencia traducida.","RESPUESTA_CORRECTA":"C","EXPLICACION":"Tiende a abrir la cromatina y facilita que la maquinaria de transcripción acceda al ADN.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"351–381"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"transcripcion y maduracion del arn","DIFICULTAD":"dificil","PREGUNTA":"¿Qué diferencia hay entre activar un gen y estabilizar el ARN que produce?","OPCION_A":"Reconocen secuencias del ADN y ayudan a reclutar o regular la ARN polimerasa.","OPCION_B":"Lo primero aumenta su transcripción; lo segundo prolonga la vida del ARN ya formado.","OPCION_C":"Transcripción convierte ADN en ARN; traducción usa el ARN mensajero para sintetizar proteína.","OPCION_D":"Entre otros factores, sus secuencias, proteínas asociadas y mecanismos celulares de degradación.","RESPUESTA_CORRECTA":"B","EXPLICACION":"Lo primero aumenta su transcripción; lo segundo prolonga la vida del ARN ya formado.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"351–381"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"transcripcion y maduracion del arn","DIFICULTAD":"medio","PREGUNTA":"Si se degrada más rápido un ARN mensajero, ¿qué suele pasar con su proteína?","OPCION_A":"Puede bloquear su traducción o favorecer su degradación.","OPCION_B":"Puede producirse menos ARN y, en muchos casos, menos proteína.","OPCION_C":"Puede disminuir su producción aunque el gen siga transcribiéndose.","OPCION_D":"Ayuda a protegerlo y favorece su procesamiento, exportación y traducción.","RESPUESTA_CORRECTA":"C","EXPLICACION":"Puede disminuir su producción aunque el gen siga transcribiéndose.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"351–381"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"transcripcion y maduracion del arn","DIFICULTAD":"dificil","PREGUNTA":"¿Por qué una célula puede responder rápido a una señal sin cambiar su ADN?","OPCION_A":"Puede activar o frenar la expresión de genes existentes.","OPCION_B":"Así ajusta con rapidez cuánto tiempo se produce su proteína.","OPCION_C":"Puede modificar la región final del ARN y su regulación o la proteína resultante.","OPCION_D":"Aún debe procesarse y unirse a proteínas en subunidades ribosómicas.","RESPUESTA_CORRECTA":"A","EXPLICACION":"Puede activar o frenar la expresión de genes existentes.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"351–381"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"transcripcion y maduracion del arn","DIFICULTAD":"medio","PREGUNTA":"¿Qué ocurre si un promotor queda silenciado por cambios epigenéticos?","OPCION_A":"El nucléolo produce componentes ribosómicos que luego funcionarán en el citoplasma.","OPCION_B":"La activación de la transcripción, el procesamiento y la estabilidad del ARN.","OPCION_C":"La transcripción de ese gen puede disminuir o detenerse sin cambiar su secuencia.","OPCION_D":"El conjunto de cambios que transforma un transcrito inicial en ARN funcional.","RESPUESTA_CORRECTA":"C","EXPLICACION":"La transcripción de ese gen puede disminuir o detenerse sin cambiar su secuencia.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"351–381"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"transcripcion y maduracion del arn","DIFICULTAD":"facil","PREGUNTA":"¿Dónde se forma principalmente el precursor del ARN ribosómico 45 S?","OPCION_A":"En el nucléolo.","OPCION_B":"En dirección 5'' a 3''.","OPCION_C":"En secuencias reguladoras como el promotor.","OPCION_D":"Por complementariedad entre sus secuencias de bases.","RESPUESTA_CORRECTA":"A","EXPLICACION":"En el nucléolo.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"351–381"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"transcripcion y maduracion del arn","DIFICULTAD":"facil","PREGUNTA":"¿Qué es el nucléolo dentro del núcleo?","OPCION_A":"El nucléolo produce componentes ribosómicos que luego funcionarán en el citoplasma.","OPCION_B":"Una región organizada donde se transcribe y procesa gran parte del ARN ribosómico y comienza el ensamblaje ribosomal.","OPCION_C":"La replicación copia el ADN para conservar el genoma; la transcripción produce ARN de genes seleccionados.","OPCION_D":"El recién transcrito todavía puede necesitar cortes, modificaciones y otras etapas de procesamiento.","RESPUESTA_CORRECTA":"B","EXPLICACION":"Una región organizada donde se transcribe y procesa gran parte del ARN ribosómico y comienza el ensamblaje ribosomal.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"351–381"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"transcripcion y maduracion del arn","DIFICULTAD":"dificil","PREGUNTA":"¿Por qué un nucléolo grande puede indicar intensa síntesis de proteínas?","OPCION_A":"Porque ambas determinan cuánto ARN funcional queda disponible en cada momento.","OPCION_B":"Porque producir ribosomas requiere mucho ARN ribosómico y ensamblaje de subunidades.","OPCION_C":"Porque altera la forma del ARN y puede producir una proteína distinta o no funcional.","OPCION_D":"Porque aún contiene intrones y secuencias que se eliminan durante la maduración.","RESPUESTA_CORRECTA":"B","EXPLICACION":"Porque producir ribosomas requiere mucho ARN ribosómico y ensamblaje de subunidades.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"351–381"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"transcripcion y maduracion del arn","DIFICULTAD":"facil","PREGUNTA":"¿Qué componente del nucléolo sirve de punto de partida para fabricar pre-ARN ribosómico?","OPCION_A":"Los ARN ribosómicos 18 S, 5.8 S y 28 S.","OPCION_B":"Las regiones de ADN con genes ribosómicos.","OPCION_C":"El ARN contiene ribosa; el ADN, desoxirribosa.","OPCION_D":"Una cola poli(A), formada por numerosas adeninas.","RESPUESTA_CORRECTA":"B","EXPLICACION":"Las regiones de ADN con genes ribosómicos.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"351–381"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"transcripcion y maduracion del arn","DIFICULTAD":"facil","PREGUNTA":"¿Qué significan las regiones organizadoras nucleolares?","OPCION_A":"Transcripción convierte ADN en ARN; traducción usa el ARN mensajero para sintetizar proteína.","OPCION_B":"Zonas cromosómicas con genes de ARN ribosómico que participan en la formación del nucléolo.","OPCION_C":"Entre otros factores, sus secuencias, proteínas asociadas y mecanismos celulares de degradación.","OPCION_D":"Lo primero aumenta su transcripción; lo segundo prolonga la vida del ARN ya formado.","RESPUESTA_CORRECTA":"B","EXPLICACION":"Zonas cromosómicas con genes de ARN ribosómico que participan en la formación del nucléolo.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"351–381"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"transcripcion y maduracion del arn","DIFICULTAD":"facil","PREGUNTA":"¿Qué ocurre con el precursor ribosómico 45 S antes de formar ribosomas?","OPCION_A":"Se cortan y modifican antes de ensamblarse con proteínas ribosómicas.","OPCION_B":"Se corta y modifica para originar distintos ARN ribosómicos maduros.","OPCION_C":"Se recortan sus extremos y se modifican varias bases; algunos precursores también pierden intrones.","OPCION_D":"Que es un patrón de bases frecuente en promotores de distintos genes.","RESPUESTA_CORRECTA":"B","EXPLICACION":"Se corta y modifica para originar distintos ARN ribosómicos maduros.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"351–381"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"transcripcion y maduracion del arn","DIFICULTAD":"facil","PREGUNTA":"¿Qué ARN ribosómicos se obtienen del precursor 45 S?","OPCION_A":"La ARN polimerasa I.","OPCION_B":"El ARN contiene ribosa; el ADN, desoxirribosa.","OPCION_C":"Los ARN ribosómicos 18 S, 5.8 S y 28 S.","OPCION_D":"Las regiones de ADN con genes ribosómicos.","RESPUESTA_CORRECTA":"C","EXPLICACION":"Los ARN ribosómicos 18 S, 5.8 S y 28 S.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"351–381"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"transcripcion y maduracion del arn","DIFICULTAD":"facil","PREGUNTA":"¿Dónde se transcribe el ARN ribosómico 5 S?","OPCION_A":"Fuera del nucléolo, antes de incorporarse al ensamblaje ribosomal.","OPCION_B":"En secuencias reguladoras como el promotor.","OPCION_C":"Por complementariedad entre sus secuencias de bases.","OPCION_D":"Por el corte y empalme alternativo de su ARN, entre otros mecanismos.","RESPUESTA_CORRECTA":"A","EXPLICACION":"Fuera del nucléolo, antes de incorporarse al ensamblaje ribosomal.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"351–381"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"transcripcion y maduracion del arn","DIFICULTAD":"facil","PREGUNTA":"¿Qué ARN ribosómico participa en la subunidad pequeña del ribosoma eucariota?","OPCION_A":"El ARN de transferencia.","OPCION_B":"El ARN mensajero.","OPCION_C":"El ARN ribosómico 18 S.","OPCION_D":"El ARN contiene ribosa; el ADN, desoxirribosa.","RESPUESTA_CORRECTA":"C","EXPLICACION":"El ARN ribosómico 18 S.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"351–381"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"transcripcion y maduracion del arn","DIFICULTAD":"facil","PREGUNTA":"¿Qué ARN ribosómicos se incorporan a la subunidad grande eucariota?","OPCION_A":"Los ARN ribosómicos 5 S, 5.8 S y 28 S.","OPCION_B":"El ARN ribosómico 18 S.","OPCION_C":"Una caperuza con 7-metilguanosina.","OPCION_D":"Las regiones de ADN con genes ribosómicos.","RESPUESTA_CORRECTA":"A","EXPLICACION":"Los ARN ribosómicos 5 S, 5.8 S y 28 S.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"351–381"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"transcripcion y maduracion del arn","DIFICULTAD":"facil","PREGUNTA":"¿Cómo se llama la subunidad pequeña del ribosoma eucariota?","OPCION_A":"Subunidad 40 S.","OPCION_B":"Ribozima.","OPCION_C":"Transcrito primario o pre-ARN.","OPCION_D":"Su promotor.","RESPUESTA_CORRECTA":"A","EXPLICACION":"Subunidad 40 S.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"351–381"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"transcripcion y maduracion del arn","DIFICULTAD":"facil","PREGUNTA":"¿Cómo se llama la subunidad grande del ribosoma eucariota?","OPCION_A":"Subunidad 60 S.","OPCION_B":"Ribozima.","OPCION_C":"Transcrito primario o pre-ARN.","OPCION_D":"Su promotor.","RESPUESTA_CORRECTA":"A","EXPLICACION":"Subunidad 60 S.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"351–381"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"transcripcion y maduracion del arn","DIFICULTAD":"facil","PREGUNTA":"¿Qué más necesita un ribosoma además de ARN ribosómico?","OPCION_A":"Proteínas ribosómicas que se ensamblan con esos ARN.","OPCION_B":"Proteínas ribosómicas, formando las subunidades del ribosoma.","OPCION_C":"Suele volverse menos estable y más susceptible a degradación.","OPCION_D":"Reconocen codones y llevan el aminoácido correspondiente al ribosoma.","RESPUESTA_CORRECTA":"A","EXPLICACION":"Proteínas ribosómicas que se ensamblan con esos ARN.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"351–381"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"transcripcion y maduracion del arn","DIFICULTAD":"facil","PREGUNTA":"¿Qué ocurre con las subunidades ribosómicas tras su ensamblaje inicial?","OPCION_A":"Se corta y modifica para originar distintos ARN ribosómicos maduros.","OPCION_B":"Se exportan al citoplasma, donde participarán en la traducción.","OPCION_C":"Se cortan y modifican antes de ensamblarse con proteínas ribosómicas.","OPCION_D":"Que es un patrón de bases frecuente en promotores de distintos genes.","RESPUESTA_CORRECTA":"B","EXPLICACION":"Se exportan al citoplasma, donde participarán en la traducción.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"351–381"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"transcripcion y maduracion del arn","DIFICULTAD":"facil","PREGUNTA":"¿Qué es la maduración postranscripcional del ARN?","OPCION_A":"El conjunto de cambios que transforma un transcrito inicial en ARN funcional.","OPCION_B":"Un ARN pequeño que puede unirse a ARN mensajeros y regular su expresión.","OPCION_C":"La traducción, la acción de ARN reguladores y la estabilidad de la proteína.","OPCION_D":"La activación de la transcripción, el procesamiento y la estabilidad del ARN.","RESPUESTA_CORRECTA":"A","EXPLICACION":"El conjunto de cambios que transforma un transcrito inicial en ARN funcional.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"351–381"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"transcripcion y maduracion del arn","DIFICULTAD":"facil","PREGUNTA":"En un pre-ARN mensajero, ¿qué se elimina por corte y empalme?","OPCION_A":"El espliceosoma.","OPCION_B":"Los intrones.","OPCION_C":"La ARN polimerasa II.","OPCION_D":"El ARN ribosómico.","RESPUESTA_CORRECTA":"B","EXPLICACION":"Los intrones.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"351–381"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"transcripcion y maduracion del arn","DIFICULTAD":"facil","PREGUNTA":"Después de retirar intrones, ¿qué regiones se unen?","OPCION_A":"Los intrones.","OPCION_B":"El espliceosoma.","OPCION_C":"Los exones.","OPCION_D":"El ARN mensajero.","RESPUESTA_CORRECTA":"C","EXPLICACION":"Los exones.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"351–381"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"transcripcion y maduracion del arn","DIFICULTAD":"facil","PREGUNTA":"¿Qué complejo lleva a cabo gran parte del corte y empalme del pre-ARN mensajero nuclear?","OPCION_A":"El espliceosoma.","OPCION_B":"El ARN mensajero.","OPCION_C":"La ARN polimerasa II.","OPCION_D":"El ARN ribosómico.","RESPUESTA_CORRECTA":"A","EXPLICACION":"El espliceosoma.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"351–381"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"transcripcion y maduracion del arn","DIFICULTAD":"facil","PREGUNTA":"¿Qué partículas pequeñas con ARN y proteínas ayudan al espliceosoma?","OPCION_A":"Una cola poli(A), formada por numerosas adeninas.","OPCION_B":"El ARN contiene ribosa; el ADN, desoxirribosa.","OPCION_C":"Las snRNP, ribonucleoproteínas nucleares pequeñas.","OPCION_D":"Los ARN ribosómicos 18 S, 5.8 S y 28 S.","RESPUESTA_CORRECTA":"C","EXPLICACION":"Las snRNP, ribonucleoproteínas nucleares pequeñas.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"351–381"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"transcripcion y maduracion del arn","DIFICULTAD":"dificil","PREGUNTA":"¿Por qué un error en el sitio de corte y empalme puede alterar una proteína?","OPCION_A":"Puede cambiar qué exones quedan en el ARN maduro y, con ello, la secuencia traducida.","OPCION_B":"Pueden diferir en transcripción, procesamiento, estabilidad o traducción del ARN.","OPCION_C":"Tiende a abrir la cromatina y facilita que la maquinaria de transcripción acceda al ADN.","OPCION_D":"Puede modificar la región final del ARN y su regulación o la proteína resultante.","RESPUESTA_CORRECTA":"A","EXPLICACION":"Puede cambiar qué exones quedan en el ARN maduro y, con ello, la secuencia traducida.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"351–381"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"transcripcion y maduracion del arn","DIFICULTAD":"facil","PREGUNTA":"¿Qué significa corte y empalme alternativo?","OPCION_A":"Permite generar varias proteínas a partir de una misma región genética.","OPCION_B":"Mueven o reorganizan nucleosomas para cambiar el acceso al ADN.","OPCION_C":"Elegir combinaciones distintas de exones de un mismo transcrito.","OPCION_D":"Proteínas ribosómicas, formando las subunidades del ribosoma.","RESPUESTA_CORRECTA":"C","EXPLICACION":"Elegir combinaciones distintas de exones de un mismo transcrito.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"351–381"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"transcripcion y maduracion del arn","DIFICULTAD":"facil","PREGUNTA":"¿Cómo puede un solo gen dar lugar a varias proteínas?","OPCION_A":"Por complementariedad entre sus secuencias de bases.","OPCION_B":"Por el corte y empalme alternativo de su ARN, entre otros mecanismos.","OPCION_C":"Fuera del nucléolo, antes de incorporarse al ensamblaje ribosomal.","OPCION_D":"En secuencias reguladoras como el promotor.","RESPUESTA_CORRECTA":"B","EXPLICACION":"Por el corte y empalme alternativo de su ARN, entre otros mecanismos.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"351–381"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"transcripcion y maduracion del arn","DIFICULTAD":"facil","PREGUNTA":"¿Cómo se llama un ARN capaz de catalizar una reacción?","OPCION_A":"Subunidad 40 S.","OPCION_B":"Transcrito primario o pre-ARN.","OPCION_C":"Guanina.","OPCION_D":"Ribozima.","RESPUESTA_CORRECTA":"D","EXPLICACION":"Ribozima.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"351–381"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"transcripcion y maduracion del arn","DIFICULTAD":"facil","PREGUNTA":"¿Qué modificación protectora se añade al extremo 5'' de muchos ARN mensajeros?","OPCION_A":"Una cola poli(A), formada por numerosas adeninas.","OPCION_B":"Los ARN ribosómicos 18 S, 5.8 S y 28 S.","OPCION_C":"Una caperuza con 7-metilguanosina.","OPCION_D":"La elongación de la cadena de ARN.","RESPUESTA_CORRECTA":"C","EXPLICACION":"Una caperuza con 7-metilguanosina.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"351–381"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"transcripcion y maduracion del arn","DIFICULTAD":"facil","PREGUNTA":"¿Para qué sirve la caperuza del extremo 5'' del ARN mensajero?","OPCION_A":"A través de complejos de poro nuclear, asociado a proteínas de transporte.","OPCION_B":"Puede modificar la región final del ARN y su regulación o la proteína resultante.","OPCION_C":"Ayuda a protegerlo y favorece su procesamiento, exportación y traducción.","OPCION_D":"Suele volverse menos estable y más susceptible a degradación.","RESPUESTA_CORRECTA":"C","EXPLICACION":"Ayuda a protegerlo y favorece su procesamiento, exportación y traducción.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"351–381"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"transcripcion y maduracion del arn","DIFICULTAD":"facil","PREGUNTA":"¿Qué se añade al extremo 3'' de muchos ARN mensajeros maduros?","OPCION_A":"Una caperuza con 7-metilguanosina.","OPCION_B":"Las snRNP, ribonucleoproteínas nucleares pequeñas.","OPCION_C":"El ARN contiene ribosa; el ADN, desoxirribosa.","OPCION_D":"Una cola poli(A), formada por numerosas adeninas.","RESPUESTA_CORRECTA":"D","EXPLICACION":"Una cola poli(A), formada por numerosas adeninas.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"351–381"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"transcripcion y maduracion del arn","DIFICULTAD":"facil","PREGUNTA":"¿Qué puede ocurrir con un ARN mensajero que pierde su cola poli(A)?","OPCION_A":"Proteínas ribosómicas, formando las subunidades del ribosoma.","OPCION_B":"Reconocen codones y llevan el aminoácido correspondiente al ribosoma.","OPCION_C":"Suele volverse menos estable y más susceptible a degradación.","OPCION_D":"Entre otros factores, sus secuencias, proteínas asociadas y mecanismos celulares de degradación.","RESPUESTA_CORRECTA":"C","EXPLICACION":"Suele volverse menos estable y más susceptible a degradación.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"351–381"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"transcripcion y maduracion del arn","DIFICULTAD":"dificil","PREGUNTA":"¿Por qué cortar el extremo 3'' del ARN en sitios distintos puede cambiar su producto?","OPCION_A":"Estas proteínas ayudan a procesarlo, protegerlo, localizarlo y transportarlo.","OPCION_B":"Aún debe procesarse y unirse a proteínas en subunidades ribosómicas.","OPCION_C":"Pueden diferir en transcripción, procesamiento, estabilidad o traducción del ARN.","OPCION_D":"Puede modificar la región final del ARN y su regulación o la proteína resultante.","RESPUESTA_CORRECTA":"D","EXPLICACION":"Puede modificar la región final del ARN y su regulación o la proteína resultante.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"351–381"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"transcripcion y maduracion del arn","DIFICULTAD":"facil","PREGUNTA":"¿Qué debe pasarle al precursor del ARN de transferencia antes de funcionar?","OPCION_A":"Se corta y modifica para originar distintos ARN ribosómicos maduros.","OPCION_B":"Se cortan y modifican antes de ensamblarse con proteínas ribosómicas.","OPCION_C":"Se recortan sus extremos y se modifican varias bases; algunos precursores también pierden intrones.","OPCION_D":"Que es un patrón de bases frecuente en promotores de distintos genes.","RESPUESTA_CORRECTA":"C","EXPLICACION":"Se recortan sus extremos y se modifican varias bases; algunos precursores también pierden intrones.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"351–381"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"transcripcion y maduracion del arn","DIFICULTAD":"dificil","PREGUNTA":"¿Por qué el ARN de transferencia contiene bases poco habituales?","OPCION_A":"Porque muchas bases se modifican químicamente durante su maduración.","OPCION_B":"Porque ambas determinan cuánto ARN funcional queda disponible en cada momento.","OPCION_C":"Porque aún contiene intrones y secuencias que se eliminan durante la maduración.","OPCION_D":"Porque altera la forma del ARN y puede producir una proteína distinta o no funcional.","RESPUESTA_CORRECTA":"A","EXPLICACION":"Porque muchas bases se modifican químicamente durante su maduración.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"351–381"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"transcripcion y maduracion del arn","DIFICULTAD":"facil","PREGUNTA":"¿Qué labor general realizan los ARN de transferencia maduros?","OPCION_A":"Suele volverse menos estable y más susceptible a degradación.","OPCION_B":"Proteínas ribosómicas, formando las subunidades del ribosoma.","OPCION_C":"Reconocen codones y llevan el aminoácido correspondiente al ribosoma.","OPCION_D":"Reconocen secuencias del ADN y ayudan a reclutar o regular la ARN polimerasa.","RESPUESTA_CORRECTA":"C","EXPLICACION":"Reconocen codones y llevan el aminoácido correspondiente al ribosoma.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"351–381"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"transcripcion y maduracion del arn","DIFICULTAD":"facil","PREGUNTA":"¿Qué ocurre con los precursores de ARN ribosómico durante su maduración?","OPCION_A":"Se corta y modifica para originar distintos ARN ribosómicos maduros.","OPCION_B":"Se cortan y modifican antes de ensamblarse con proteínas ribosómicas.","OPCION_C":"Que es un patrón de bases frecuente en promotores de distintos genes.","OPCION_D":"Se degrada y sus componentes pueden reutilizarse.","RESPUESTA_CORRECTA":"B","EXPLICACION":"Se cortan y modifican antes de ensamblarse con proteínas ribosómicas.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"351–381"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"transcripcion y maduracion del arn","DIFICULTAD":"dificil","PREGUNTA":"¿Por qué no basta transcribir el ARN ribosómico para tener un ribosoma funcional?","OPCION_A":"Así ajusta con rapidez cuánto tiempo se produce su proteína.","OPCION_B":"Aún debe procesarse y unirse a proteínas en subunidades ribosómicas.","OPCION_C":"Estas proteínas ayudan a procesarlo, protegerlo, localizarlo y transportarlo.","OPCION_D":"Puede modificar la región final del ARN y su regulación o la proteína resultante.","RESPUESTA_CORRECTA":"B","EXPLICACION":"Aún debe procesarse y unirse a proteínas en subunidades ribosómicas.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"351–381"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"transcripcion y maduracion del arn","DIFICULTAD":"facil","PREGUNTA":"¿Cómo sale del núcleo un ARN mensajero ya procesado?","OPCION_A":"Ayuda a protegerlo y favorece su procesamiento, exportación y traducción.","OPCION_B":"Suele volverse menos estable y más susceptible a degradación.","OPCION_C":"A través de complejos de poro nuclear, asociado a proteínas de transporte.","OPCION_D":"Entre otros factores, sus secuencias, proteínas asociadas y mecanismos celulares de degradación.","RESPUESTA_CORRECTA":"C","EXPLICACION":"A través de complejos de poro nuclear, asociado a proteínas de transporte.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"351–381"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"transcripcion y maduracion del arn","DIFICULTAD":"dificil","PREGUNTA":"¿Por qué el ARN viaja unido a proteínas dentro de la célula?","OPCION_A":"Puede modificar la región final del ARN y su regulación o la proteína resultante.","OPCION_B":"Aún debe procesarse y unirse a proteínas en subunidades ribosómicas.","OPCION_C":"Estas proteínas ayudan a procesarlo, protegerlo, localizarlo y transportarlo.","OPCION_D":"Así ajusta con rapidez cuánto tiempo se produce su proteína.","RESPUESTA_CORRECTA":"C","EXPLICACION":"Estas proteínas ayudan a procesarlo, protegerlo, localizarlo y transportarlo.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"351–381"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"transcripcion y maduracion del arn","DIFICULTAD":"facil","PREGUNTA":"¿Qué puede pasar con un ARN mensajero cuando ya cumplió su función?","OPCION_A":"Se degrada y sus componentes pueden reutilizarse.","OPCION_B":"Se cortan y modifican antes de ensamblarse con proteínas ribosómicas.","OPCION_C":"Se exportan al citoplasma, donde participarán en la traducción.","OPCION_D":"Se corta y modifica para originar distintos ARN ribosómicos maduros.","RESPUESTA_CORRECTA":"A","EXPLICACION":"Se degrada y sus componentes pueden reutilizarse.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"351–381"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"transcripcion y maduracion del arn","DIFICULTAD":"facil","PREGUNTA":"¿Qué controla la vida media de un ARN mensajero?","OPCION_A":"Transcripción convierte ADN en ARN; traducción usa el ARN mensajero para sintetizar proteína.","OPCION_B":"Entre otros factores, sus secuencias, proteínas asociadas y mecanismos celulares de degradación.","OPCION_C":"Lo primero aumenta su transcripción; lo segundo prolonga la vida del ARN ya formado.","OPCION_D":"Suele volverse menos estable y más susceptible a degradación.","RESPUESTA_CORRECTA":"B","EXPLICACION":"Entre otros factores, sus secuencias, proteínas asociadas y mecanismos celulares de degradación.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"351–381"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"transcripcion y maduracion del arn","DIFICULTAD":"facil","PREGUNTA":"¿Qué es un micro-ARN?","OPCION_A":"El conjunto de cambios que transforma un transcrito inicial en ARN funcional.","OPCION_B":"Los intrones; los exones se unen para formar el ARN mensajero maduro.","OPCION_C":"La traducción, la acción de ARN reguladores y la estabilidad de la proteína.","OPCION_D":"Un ARN pequeño que puede unirse a ARN mensajeros y regular su expresión.","RESPUESTA_CORRECTA":"D","EXPLICACION":"Un ARN pequeño que puede unirse a ARN mensajeros y regular su expresión.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"351–381"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"transcripcion y maduracion del arn","DIFICULTAD":"facil","PREGUNTA":"¿Cómo reconoce un micro-ARN a su ARN mensajero diana?","OPCION_A":"Por el corte y empalme alternativo de su ARN, entre otros mecanismos.","OPCION_B":"Por complementariedad entre sus secuencias de bases.","OPCION_C":"Fuera del nucléolo, antes de incorporarse al ensamblaje ribosomal.","OPCION_D":"En secuencias reguladoras como el promotor.","RESPUESTA_CORRECTA":"B","EXPLICACION":"Por complementariedad entre sus secuencias de bases.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"351–381"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"transcripcion y maduracion del arn","DIFICULTAD":"medio","PREGUNTA":"Si un micro-ARN se une a un ARN mensajero, ¿qué puede pasar?","OPCION_A":"Puede bloquear su traducción o favorecer su degradación.","OPCION_B":"Puede disminuir su producción aunque el gen siga transcribiéndose.","OPCION_C":"Puede producirse menos ARN y, en muchos casos, menos proteína.","OPCION_D":"Suele volverse menos estable y más susceptible a degradación.","RESPUESTA_CORRECTA":"A","EXPLICACION":"Puede bloquear su traducción o favorecer su degradación.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"351–381"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"transcripcion y maduracion del arn","DIFICULTAD":"dificil","PREGUNTA":"¿Por qué dos células pueden fabricar cantidades distintas de proteína a partir del mismo gen?","OPCION_A":"Puede cambiar qué exones quedan en el ARN maduro y, con ello, la secuencia traducida.","OPCION_B":"Tiende a abrir la cromatina y facilita que la maquinaria de transcripción acceda al ADN.","OPCION_C":"Su actividad se regula según el tipo de célula, las señales y las necesidades del momento.","OPCION_D":"Pueden diferir en transcripción, procesamiento, estabilidad o traducción del ARN.","RESPUESTA_CORRECTA":"D","EXPLICACION":"Pueden diferir en transcripción, procesamiento, estabilidad o traducción del ARN.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"351–381"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"transcripcion y maduracion del arn","DIFICULTAD":"dificil","PREGUNTA":"¿Qué diferencia hay entre ARN mensajero y ARN ribosómico?","OPCION_A":"El mensajero lleva una secuencia para traducir; el ribosómico forma parte del ribosoma.","OPCION_B":"El mensajero porta codones; el de transferencia aporta aminoácidos y reconoce esos codones.","OPCION_C":"El recién transcrito todavía puede necesitar cortes, modificaciones y otras etapas de procesamiento.","OPCION_D":"La replicación copia el ADN para conservar el genoma; la transcripción produce ARN de genes seleccionados.","RESPUESTA_CORRECTA":"A","EXPLICACION":"El mensajero lleva una secuencia para traducir; el ribosómico forma parte del ribosoma.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"351–381"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"transcripcion y maduracion del arn","DIFICULTAD":"dificil","PREGUNTA":"¿Qué diferencia hay entre ARN mensajero y ARN de transferencia?","OPCION_A":"El mensajero lleva una secuencia para traducir; el ribosómico forma parte del ribosoma.","OPCION_B":"El recién transcrito todavía puede necesitar cortes, modificaciones y otras etapas de procesamiento.","OPCION_C":"El mensajero porta codones; el de transferencia aporta aminoácidos y reconoce esos codones.","OPCION_D":"La replicación copia el ADN para conservar el genoma; la transcripción produce ARN de genes seleccionados.","RESPUESTA_CORRECTA":"C","EXPLICACION":"El mensajero porta codones; el de transferencia aporta aminoácidos y reconoce esos codones.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"351–381"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"transcripcion y maduracion del arn","DIFICULTAD":"dificil","PREGUNTA":"¿Por qué un cambio en el splicing puede causar enfermedad sin cambiar la cantidad de ARN?","OPCION_A":"Porque ambas determinan cuánto ARN funcional queda disponible en cada momento.","OPCION_B":"Porque aún contiene intrones y secuencias que se eliminan durante la maduración.","OPCION_C":"Porque producir ribosomas requiere mucho ARN ribosómico y ensamblaje de subunidades.","OPCION_D":"Porque altera la forma del ARN y puede producir una proteína distinta o no funcional.","RESPUESTA_CORRECTA":"D","EXPLICACION":"Porque altera la forma del ARN y puede producir una proteína distinta o no funcional.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"351–381"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"transcripcion y maduracion del arn","DIFICULTAD":"medio","PREGUNTA":"Si un gen está activo pero su ARN no sale del núcleo, ¿qué paso falló?","OPCION_A":"El ARN lleva uracilo donde la hebra codificante de ADN tiene timina.","OPCION_B":"Los factores y la ARN polimerasa acceden con más dificultad al ADN.","OPCION_C":"La activación de la transcripción, el procesamiento y la estabilidad del ARN.","OPCION_D":"El procesamiento o la exportación del ARN hacia el citoplasma.","RESPUESTA_CORRECTA":"D","EXPLICACION":"El procesamiento o la exportación del ARN hacia el citoplasma.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"351–381"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"transcripcion y maduracion del arn","DIFICULTAD":"facil","PREGUNTA":"¿Qué proceso convierte ADN en ARN y cuál convierte ARN mensajero en proteína?","OPCION_A":"Entre otros factores, sus secuencias, proteínas asociadas y mecanismos celulares de degradación.","OPCION_B":"Transcripción convierte ADN en ARN; traducción usa el ARN mensajero para sintetizar proteína.","OPCION_C":"Lo primero aumenta su transcripción; lo segundo prolonga la vida del ARN ya formado.","OPCION_D":"Suele volverse menos estable y más susceptible a degradación.","RESPUESTA_CORRECTA":"B","EXPLICACION":"Transcripción convierte ADN en ARN; traducción usa el ARN mensajero para sintetizar proteína.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"351–381"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"transcripcion y maduracion del arn","DIFICULTAD":"facil","PREGUNTA":"¿Qué relación hay entre el nucléolo y la traducción que ocurre fuera del núcleo?","OPCION_A":"Una región organizada donde se transcribe y procesa gran parte del ARN ribosómico y comienza el ensamblaje ribosomal.","OPCION_B":"El mensajero lleva una secuencia para traducir; el ribosómico forma parte del ribosoma.","OPCION_C":"El mensajero porta codones; el de transferencia aporta aminoácidos y reconoce esos codones.","OPCION_D":"El nucléolo produce componentes ribosómicos que luego funcionarán en el citoplasma.","RESPUESTA_CORRECTA":"D","EXPLICACION":"El nucléolo produce componentes ribosómicos que luego funcionarán en el citoplasma.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"351–381"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"transcripcion y maduracion del arn","DIFICULTAD":"dificil","PREGUNTA":"¿Por qué es útil que una célula pueda degradar selectivamente un ARN?","OPCION_A":"Aún debe procesarse y unirse a proteínas en subunidades ribosómicas.","OPCION_B":"Así ajusta con rapidez cuánto tiempo se produce su proteína.","OPCION_C":"Estas proteínas ayudan a procesarlo, protegerlo, localizarlo y transportarlo.","OPCION_D":"Puede activar o frenar la expresión de genes existentes.","RESPUESTA_CORRECTA":"B","EXPLICACION":"Así ajusta con rapidez cuánto tiempo se produce su proteína.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"351–381"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"transcripcion y maduracion del arn","DIFICULTAD":"medio","PREGUNTA":"¿Qué se conserva del ADN en una transcripción normal?","OPCION_A":"La polimerasa deja de sintetizar y se libera el ARN producido.","OPCION_B":"La activación de la transcripción, el procesamiento y la estabilidad del ARN.","OPCION_C":"Una molécula de ARN a partir de la información contenida en el ADN.","OPCION_D":"El ADN sirve de molde, pero no se consume ni se convierte en ARN.","RESPUESTA_CORRECTA":"D","EXPLICACION":"El ADN sirve de molde, pero no se consume ni se convierte en ARN.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"351–381"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"transcripcion y maduracion del arn","DIFICULTAD":"dificil","PREGUNTA":"¿Qué diferencia de azúcar hay entre ADN y ARN?","OPCION_A":"El ARN de transferencia.","OPCION_B":"El ARN ribosómico 18 S.","OPCION_C":"El ARN mensajero.","OPCION_D":"El ARN contiene ribosa; el ADN, desoxirribosa.","RESPUESTA_CORRECTA":"D","EXPLICACION":"El ARN contiene ribosa; el ADN, desoxirribosa.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"351–381"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"transcripcion y maduracion del arn","DIFICULTAD":"dificil","PREGUNTA":"¿Por qué un mismo gen puede producir resultados distintos en dos tejidos?","OPCION_A":"Porque altera la forma del ARN y puede producir una proteína distinta o no funcional.","OPCION_B":"Porque el procesamiento alternativo y otros controles de expresión pueden variar entre tejidos.","OPCION_C":"Porque producir ribosomas requiere mucho ARN ribosómico y ensamblaje de subunidades.","OPCION_D":"Porque aún contiene intrones y secuencias que se eliminan durante la maduración.","RESPUESTA_CORRECTA":"B","EXPLICACION":"Porque el procesamiento alternativo y otros controles de expresión pueden variar entre tejidos.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"351–381"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"transcripcion y maduracion del arn","DIFICULTAD":"medio","PREGUNTA":"¿Qué paso revisas si el ADN del gen está intacto pero falta su ARN mensajero?","OPCION_A":"La traducción, la acción de ARN reguladores y la estabilidad de la proteína.","OPCION_B":"La activación de la transcripción, el procesamiento y la estabilidad del ARN.","OPCION_C":"El mensajero lleva una secuencia para traducir; el ribosómico forma parte del ribosoma.","OPCION_D":"Los intrones; los exones se unen para formar el ARN mensajero maduro.","RESPUESTA_CORRECTA":"B","EXPLICACION":"La activación de la transcripción, el procesamiento y la estabilidad del ARN.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"351–381"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"transcripcion y maduracion del arn","DIFICULTAD":"medio","PREGUNTA":"¿Qué paso revisas si el ARN mensajero está presente pero falta la proteína?","OPCION_A":"La activación de la transcripción, el procesamiento y la estabilidad del ARN.","OPCION_B":"Los intrones; los exones se unen para formar el ARN mensajero maduro.","OPCION_C":"La traducción, la acción de ARN reguladores y la estabilidad de la proteína.","OPCION_D":"El mensajero lleva una secuencia para traducir; el ribosómico forma parte del ribosoma.","RESPUESTA_CORRECTA":"C","EXPLICACION":"La traducción, la acción de ARN reguladores y la estabilidad de la proteína.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"351–381"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"transcripcion y maduracion del arn","DIFICULTAD":"dificil","PREGUNTA":"¿Por qué el transcrito primario puede ser más largo que el ARN mensajero maduro?","OPCION_A":"Porque aún contiene intrones y secuencias que se eliminan durante la maduración.","OPCION_B":"Porque ambas determinan cuánto ARN funcional queda disponible en cada momento.","OPCION_C":"Porque altera la forma del ARN y puede producir una proteína distinta o no funcional.","OPCION_D":"Porque muchas bases se modifican químicamente durante su maduración.","RESPUESTA_CORRECTA":"A","EXPLICACION":"Porque aún contiene intrones y secuencias que se eliminan durante la maduración.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"351–381"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"transcripcion y maduracion del arn","DIFICULTAD":"facil","PREGUNTA":"¿En qué compartimento ocurre el splicing del pre-ARN mensajero eucariota?","OPCION_A":"En dirección 5'' a 3''.","OPCION_B":"Por complementariedad entre sus secuencias de bases.","OPCION_C":"En secuencias reguladoras como el promotor.","OPCION_D":"En el núcleo.","RESPUESTA_CORRECTA":"D","EXPLICACION":"En el núcleo.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"351–381"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"transcripcion y maduracion del arn","DIFICULTAD":"facil","PREGUNTA":"¿Qué ventaja aporta el splicing alternativo sin aumentar el número de genes?","OPCION_A":"Elegir combinaciones distintas de exones de un mismo transcrito.","OPCION_B":"Reconocen codones y llevan el aminoácido correspondiente al ribosoma.","OPCION_C":"Permite generar varias proteínas a partir de una misma región genética.","OPCION_D":"Copia la información de un gen o una región de ADN en una molécula de ARN.","RESPUESTA_CORRECTA":"C","EXPLICACION":"Permite generar varias proteínas a partir de una misma región genética.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"351–381"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"transcripcion y maduracion del arn","DIFICULTAD":"facil","PREGUNTA":"¿Qué se ensamblará con el ARN ribosómico antes de que funcione en el citoplasma?","OPCION_A":"Proteínas ribosómicas que se ensamblan con esos ARN.","OPCION_B":"Suele volverse menos estable y más susceptible a degradación.","OPCION_C":"Reconocen secuencias del ADN y ayudan a reclutar o regular la ARN polimerasa.","OPCION_D":"Proteínas ribosómicas, formando las subunidades del ribosoma.","RESPUESTA_CORRECTA":"D","EXPLICACION":"Proteínas ribosómicas, formando las subunidades del ribosoma.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"351–381"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"transcripcion y maduracion del arn","DIFICULTAD":"dificil","PREGUNTA":"¿Por qué la célula regula tanto la síntesis como la degradación del ARN?","OPCION_A":"Porque aún contiene intrones y secuencias que se eliminan durante la maduración.","OPCION_B":"Porque ambas determinan cuánto ARN funcional queda disponible en cada momento.","OPCION_C":"Porque producir ribosomas requiere mucho ARN ribosómico y ensamblaje de subunidades.","OPCION_D":"Porque altera la forma del ARN y puede producir una proteína distinta o no funcional.","RESPUESTA_CORRECTA":"B","EXPLICACION":"Porque ambas determinan cuánto ARN funcional queda disponible en cada momento.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"351–381"},{"MATERIA":"MORFOFUNCION","TEMA":"temas principales de anatomia y fisiologia","DIFICULTAD":"medio","PREGUNTA":"Si te preguntan por la forma de un órgano, ¿estás hablando de anatomía o de fisiología?","OPCION_A":"Retroalimentación negativa, porque la respuesta se opone al cambio inicial.","OPCION_B":"Contraer sus vasos para desviar sangre a zonas mejor ventiladas.","OPCION_C":"Almidón, cuya digestión empieza con amilasas y continúa en el intestino delgado.","OPCION_D":"De anatomía. La fisiología se ocupa de cómo funciona ese órgano.","RESPUESTA_CORRECTA":"D","EXPLICACION":"De anatomía. La fisiología se ocupa de cómo funciona ese órgano.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"29–69"},{"MATERIA":"MORFOFUNCION","TEMA":"temas principales de anatomia y fisiologia","DIFICULTAD":"facil","PREGUNTA":"¿Qué busca conservar el cuerpo cuando mantiene estables sus condiciones internas?","OPCION_A":"La frecuencia son latidos por minuto; el volumen sistólico es sangre expulsada por latido.","OPCION_B":"La presión ventricular desciende con todas las válvulas cerradas y volumen casi constante.","OPCION_C":"La homeostasis: una estabilidad relativa del medio interno pese a los cambios del entorno.","OPCION_D":"La pleura, con sus hojas visceral y parietal y una fina película de líquido entre ellas.","RESPUESTA_CORRECTA":"C","EXPLICACION":"La homeostasis: una estabilidad relativa del medio interno pese a los cambios del entorno.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"29–69"},{"MATERIA":"MORFOFUNCION","TEMA":"temas principales de anatomia y fisiologia","DIFICULTAD":"facil","PREGUNTA":"Cuando sube la temperatura corporal y sudas para bajarla, ¿qué tipo de retroalimentación actúa?","OPCION_A":"De anatomía. La fisiología se ocupa de cómo funciona ese órgano.","OPCION_B":"Digestión química, que descompone macromoléculas en unidades más pequeñas.","OPCION_C":"Aumenta hasta acercarse a su capacidad máxima.","OPCION_D":"Retroalimentación negativa, porque la respuesta se opone al cambio inicial.","RESPUESTA_CORRECTA":"D","EXPLICACION":"Retroalimentación negativa, porque la respuesta se opone al cambio inicial.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"29–69"},{"MATERIA":"MORFOFUNCION","TEMA":"temas principales de anatomia y fisiologia","DIFICULTAD":"facil","PREGUNTA":"En posición anatómica, ¿hacia dónde miran las palmas de las manos?","OPCION_A":"En el mediastino, entre los pulmones y detrás del esternón.","OPCION_B":"En los bronquios principales derecho e izquierdo.","OPCION_C":"Hacia delante, con el cuerpo erguido y los brazos a los lados.","OPCION_D":"En los capilares, por sus paredes muy delgadas.","RESPUESTA_CORRECTA":"C","EXPLICACION":"Hacia delante, con el cuerpo erguido y los brazos a los lados.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"29–69"},{"MATERIA":"MORFOFUNCION","TEMA":"la quimica de la vida","DIFICULTAD":"facil","PREGUNTA":"Un átomo pierde un electrón. ¿Qué carga adquiere el ion resultante?","OPCION_A":"Disminuyen la energía de activación necesaria para que la reacción ocurra.","OPCION_B":"Positiva; al perder una carga negativa queda con más protones que electrones.","OPCION_C":"Su polaridad le permite disolver muchas sustancias y facilitar sus interacciones.","OPCION_D":"Mayor concentración de H+; por eso la solución es más ácida.","RESPUESTA_CORRECTA":"B","EXPLICACION":"Positiva; al perder una carga negativa queda con más protones que electrones.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"70–105"},{"MATERIA":"MORFOFUNCION","TEMA":"la quimica de la vida","DIFICULTAD":"facil","PREGUNTA":"¿Qué te indica un pH más bajo: mayor o menor concentración de H+?","OPCION_A":"Mayor concentración de H+; por eso la solución es más ácida.","OPCION_B":"Disminuyen la energía de activación necesaria para que la reacción ocurra.","OPCION_C":"Positiva; al perder una carga negativa queda con más protones que electrones.","OPCION_D":"Su polaridad le permite disolver muchas sustancias y facilitar sus interacciones.","RESPUESTA_CORRECTA":"A","EXPLICACION":"Mayor concentración de H+; por eso la solución es más ácida.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"70–105"},{"MATERIA":"MORFOFUNCION","TEMA":"la quimica de la vida","DIFICULTAD":"facil","PREGUNTA":"¿Qué hacen las enzimas para acelerar una reacción sin consumirse?","OPCION_A":"Mayor concentración de H+; por eso la solución es más ácida.","OPCION_B":"Disminuyen la energía de activación necesaria para que la reacción ocurra.","OPCION_C":"Positiva; al perder una carga negativa queda con más protones que electrones.","OPCION_D":"Su polaridad le permite disolver muchas sustancias y facilitar sus interacciones.","RESPUESTA_CORRECTA":"B","EXPLICACION":"Disminuyen la energía de activación necesaria para que la reacción ocurra.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"70–105"},{"MATERIA":"MORFOFUNCION","TEMA":"la quimica de la vida","DIFICULTAD":"dificil","PREGUNTA":"¿Por qué el agua es tan útil como medio de las reacciones del cuerpo?","OPCION_A":"Su polaridad le permite disolver muchas sustancias y facilitar sus interacciones.","OPCION_B":"Positiva; al perder una carga negativa queda con más protones que electrones.","OPCION_C":"Disminuyen la energía de activación necesaria para que la reacción ocurra.","OPCION_D":"Mayor concentración de H+; por eso la solución es más ácida.","RESPUESTA_CORRECTA":"A","EXPLICACION":"Su polaridad le permite disolver muchas sustancias y facilitar sus interacciones.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"70–105"},{"MATERIA":"MORFOFUNCION","TEMA":"forma y funcion celulares","DIFICULTAD":"facil","PREGUNTA":"Una célula se hincha al entrar agua. ¿Qué proceso explica ese movimiento a través de la membrana?","OPCION_A":"La mitocondria, donde ocurre gran parte de la respiración aeróbica.","OPCION_B":"La membrana plasmática.","OPCION_C":"Los activa para continuar la digestión de proteínas.","OPCION_D":"La ósmosis: el agua se desplaza a través de una membrana selectivamente permeable.","RESPUESTA_CORRECTA":"D","EXPLICACION":"La ósmosis: el agua se desplaza a través de una membrana selectivamente permeable.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"106–141"},{"MATERIA":"MORFOFUNCION","TEMA":"forma y funcion celulares","DIFICULTAD":"facil","PREGUNTA":"¿Qué estructura separa el interior celular del líquido que la rodea y regula intercambios?","OPCION_A":"La mitocondria, donde ocurre gran parte de la respiración aeróbica.","OPCION_B":"La membrana plasmática.","OPCION_C":"La ósmosis: el agua se desplaza a través de una membrana selectivamente permeable.","OPCION_D":"El nodo sinoauricular.","RESPUESTA_CORRECTA":"B","EXPLICACION":"La membrana plasmática.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"106–141"},{"MATERIA":"MORFOFUNCION","TEMA":"forma y funcion celulares","DIFICULTAD":"medio","PREGUNTA":"Si una célula necesita fabricar mucho ATP, ¿qué organelo será especialmente importante?","OPCION_A":"La ósmosis: el agua se desplaza a través de una membrana selectivamente permeable.","OPCION_B":"La membrana plasmática.","OPCION_C":"El miocardio que depende de esa arteria para recibir oxígeno.","OPCION_D":"La mitocondria, donde ocurre gran parte de la respiración aeróbica.","RESPUESTA_CORRECTA":"D","EXPLICACION":"La mitocondria, donde ocurre gran parte de la respiración aeróbica.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"106–141"},{"MATERIA":"MORFOFUNCION","TEMA":"forma y funcion celulares","DIFICULTAD":"facil","PREGUNTA":"¿Qué función cumplen las microvellosidades de la superficie celular?","OPCION_A":"Aumentan el área de superficie para procesos como la absorción.","OPCION_B":"Aumentan el área de contacto de la mucosa con el contenido intestinal.","OPCION_C":"Tos, cambios en la respiración o broncoconstricción protectora.","OPCION_D":"Manipular el alimento, formar el bolo y empujarlo para deglutir.","RESPUESTA_CORRECTA":"A","EXPLICACION":"Aumentan el área de superficie para procesos como la absorción.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"106–141"}]'::jsonb) AS p("MATERIA" text, "TEMA" text, "DIFICULTAD" text, "PREGUNTA" text, "OPCION_A" text, "OPCION_B" text, "OPCION_C" text, "OPCION_D" text, "RESPUESTA_CORRECTA" text, "EXPLICACION" text, "FUENTE" text, "PAGINAS_PDF" text)
), missing AS (
  SELECT p.* FROM payload p
  WHERE NOT EXISTS (
    SELECT 1 FROM public.banco_preguntas b
    WHERE b."MATERIA" = p."MATERIA" AND lower(b."PREGUNTA") = lower(p."PREGUNTA")
  )
), numbered AS (
  SELECT (SELECT coalesce(max(id), 0) FROM public.banco_preguntas) + row_number() OVER (ORDER BY "MATERIA", "TEMA", "PREGUNTA") AS id, m.*
  FROM missing m
)
INSERT INTO public.banco_preguntas (id, "MATERIA", "TEMA", "DIFICULTAD", "PREGUNTA", "OPCION_A", "OPCION_B", "OPCION_C", "OPCION_D", "RESPUESTA_CORRECTA", "EXPLICACION", "FUENTE", "PAGINAS_PDF")
SELECT n.id, n."MATERIA", n."TEMA", n."DIFICULTAD", n."PREGUNTA", n."OPCION_A", n."OPCION_B", n."OPCION_C", n."OPCION_D", n."RESPUESTA_CORRECTA", n."EXPLICACION", n."FUENTE", n."PAGINAS_PDF" FROM numbered n;
COMMIT;

