  SELECT * FROM jsonb_to_recordset('[{"MATERIA":"MORFOFUNCION","TEMA":"genetica y funcion celular","DIFICULTAD":"facil","PREGUNTA":"¿Qué molécula conserva las instrucciones hereditarias de la célula?","OPCION_A":"La traduce en una secuencia de aminoácidos para formar una proteína.","OPCION_B":"El ADN.","OPCION_C":"El ATP.","OPCION_D":"El bazo.","RESPUESTA_CORRECTA":"B","EXPLICACION":"El ADN.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"142–170"},{"MATERIA":"MORFOFUNCION","TEMA":"genetica y funcion celular","DIFICULTAD":"medio","PREGUNTA":"Si una célula copia la información de un gen a ARN, ¿cómo se llama ese paso?","OPCION_A":"Debe duplicarse para repartir la información genética a las células hijas.","OPCION_B":"Disminuye.","OPCION_C":"Estenosis valvular.","OPCION_D":"Transcripción.","RESPUESTA_CORRECTA":"D","EXPLICACION":"Transcripción.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"142–170"},{"MATERIA":"MORFOFUNCION","TEMA":"genetica y funcion celular","DIFICULTAD":"facil","PREGUNTA":"¿Qué hace un ribosoma con la información del ARN mensajero?","OPCION_A":"El ADN.","OPCION_B":"El interno es involuntario; el externo está bajo control voluntario.","OPCION_C":"La traduce en una secuencia de aminoácidos para formar una proteína.","OPCION_D":"La sangre puede acumularse detrás de él, en la circulación pulmonar.","RESPUESTA_CORRECTA":"C","EXPLICACION":"La traduce en una secuencia de aminoácidos para formar una proteína.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"142–170"},{"MATERIA":"MORFOFUNCION","TEMA":"genetica y funcion celular","DIFICULTAD":"medio","PREGUNTA":"Antes de que una célula se divida, ¿qué debe ocurrir con su ADN?","OPCION_A":"Debe duplicarse para repartir la información genética a las células hijas.","OPCION_B":"Transcripción.","OPCION_C":"Lo calienta, lo humedece y ayuda a limpiarlo.","OPCION_D":"La traduce en una secuencia de aminoácidos para formar una proteína.","RESPUESTA_CORRECTA":"A","EXPLICACION":"Debe duplicarse para repartir la información genética a las células hijas.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"142–170"},{"MATERIA":"MORFOFUNCION","TEMA":"histologia","DIFICULTAD":"facil","PREGUNTA":"¿Qué tejido forma una cubierta y reviste cavidades del cuerpo?","OPCION_A":"El tejido conjuntivo.","OPCION_B":"El tejido epitelial.","OPCION_C":"La pleura parietal.","OPCION_D":"La rama circunfleja.","RESPUESTA_CORRECTA":"B","EXPLICACION":"El tejido epitelial.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"171–207"},{"MATERIA":"MORFOFUNCION","TEMA":"histologia","DIFICULTAD":"facil","PREGUNTA":"¿Qué tejido suele tener células separadas por abundante matriz extracelular?","OPCION_A":"El tejido epitelial.","OPCION_B":"El tejido conjuntivo.","OPCION_C":"El ácido clorhídrico.","OPCION_D":"El epitelio olfativo.","RESPUESTA_CORRECTA":"B","EXPLICACION":"El tejido conjuntivo.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"171–207"},{"MATERIA":"MORFOFUNCION","TEMA":"histologia","DIFICULTAD":"medio","PREGUNTA":"¿Qué cuatro grandes clases de tejido debes reconocer en una lámina?","OPCION_A":"Epitelial, conjuntivo, muscular y nervioso.","OPCION_B":"Tejido muscular.","OPCION_C":"Parótidas, submandibulares y sublinguales.","OPCION_D":"El tejido epitelial.","RESPUESTA_CORRECTA":"A","EXPLICACION":"Epitelial, conjuntivo, muscular y nervioso.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"171–207"},{"MATERIA":"MORFOFUNCION","TEMA":"histologia","DIFICULTAD":"medio","PREGUNTA":"Si una muestra tiene células especializadas en contraerse, ¿qué clase de tejido es?","OPCION_A":"Tejido muscular.","OPCION_B":"Epitelial, conjuntivo, muscular y nervioso.","OPCION_C":"Transcripción.","OPCION_D":"Estenosis valvular.","RESPUESTA_CORRECTA":"A","EXPLICACION":"Tejido muscular.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"171–207"},{"MATERIA":"MORFOFUNCION","TEMA":"sistema tegumentario","DIFICULTAD":"facil","PREGUNTA":"¿Cuál es la capa más superficial de la piel?","OPCION_A":"La epidermis, un epitelio estratificado queratinizado.","OPCION_B":"Los melanocitos producen melanina.","OPCION_C":"Las glándulas sudoríparas.","OPCION_D":"La dermis.","RESPUESTA_CORRECTA":"A","EXPLICACION":"La epidermis, un epitelio estratificado queratinizado.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"208–233"},{"MATERIA":"MORFOFUNCION","TEMA":"sistema tegumentario","DIFICULTAD":"facil","PREGUNTA":"¿Qué capa de la piel contiene vasos, nervios y abundante tejido conjuntivo?","OPCION_A":"Los melanocitos producen melanina.","OPCION_B":"Las glándulas sudoríparas.","OPCION_C":"La epidermis, un epitelio estratificado queratinizado.","OPCION_D":"La dermis.","RESPUESTA_CORRECTA":"D","EXPLICACION":"La dermis.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"208–233"},{"MATERIA":"MORFOFUNCION","TEMA":"sistema tegumentario","DIFICULTAD":"facil","PREGUNTA":"Cuando sudas para perder calor, ¿qué anexo cutáneo está trabajando?","OPCION_A":"Los melanocitos producen melanina.","OPCION_B":"La dermis.","OPCION_C":"La epidermis, un epitelio estratificado queratinizado.","OPCION_D":"Las glándulas sudoríparas.","RESPUESTA_CORRECTA":"D","EXPLICACION":"Las glándulas sudoríparas.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"208–233"},{"MATERIA":"MORFOFUNCION","TEMA":"sistema tegumentario","DIFICULTAD":"facil","PREGUNTA":"¿Qué células producen el pigmento que contribuye al color de la piel?","OPCION_A":"La dermis.","OPCION_B":"La epidermis, un epitelio estratificado queratinizado.","OPCION_C":"Los melanocitos producen melanina.","OPCION_D":"Las glándulas sudoríparas.","RESPUESTA_CORRECTA":"C","EXPLICACION":"Los melanocitos producen melanina.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"208–233"},{"MATERIA":"MORFOFUNCION","TEMA":"tejido oseo","DIFICULTAD":"facil","PREGUNTA":"En un hueso en crecimiento, ¿qué célula deposita nueva matriz ósea?","OPCION_A":"El osteoblasto.","OPCION_B":"El osteoclasto.","OPCION_C":"La simpática.","OPCION_D":"Osteocito.","RESPUESTA_CORRECTA":"A","EXPLICACION":"El osteoblasto.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"234–260"},{"MATERIA":"MORFOFUNCION","TEMA":"tejido oseo","DIFICULTAD":"facil","PREGUNTA":"¿Qué célula retira matriz durante la remodelación del hueso?","OPCION_A":"El osteoblasto.","OPCION_B":"Un ligamento.","OPCION_C":"El osteoclasto.","OPCION_D":"El tejido conjuntivo.","RESPUESTA_CORRECTA":"C","EXPLICACION":"El osteoclasto.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"234–260"},{"MATERIA":"MORFOFUNCION","TEMA":"tejido oseo","DIFICULTAD":"medio","PREGUNTA":"¿Cómo se llama la célula ósea madura alojada en una laguna de la matriz?","OPCION_A":"Osteocito.","OPCION_B":"Fascículo.","OPCION_C":"Diástole.","OPCION_D":"Sinapsis.","RESPUESTA_CORRECTA":"A","EXPLICACION":"Osteocito.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"234–260"},{"MATERIA":"MORFOFUNCION","TEMA":"tejido oseo","DIFICULTAD":"dificil","PREGUNTA":"¿Por qué el esqueleto también participa en la regulación de minerales?","OPCION_A":"Porque el impulso se regenera principalmente en los nodos de Ranvier y salta entre ellos.","OPCION_B":"Porque el corazón ocupa parte del lado izquierdo del mediastino.","OPCION_C":"Porque eleva el pH duodenal hasta un rango más favorable para su actividad.","OPCION_D":"Porque el hueso almacena y libera minerales, especialmente calcio y fosfato.","RESPUESTA_CORRECTA":"D","EXPLICACION":"Porque el hueso almacena y libera minerales, especialmente calcio y fosfato.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"234–260"},{"MATERIA":"MORFOFUNCION","TEMA":"el sistema oseo","DIFICULTAD":"facil","PREGUNTA":"¿Qué estructuras pertenecen al esqueleto axial?","OPCION_A":"Diáfisis.","OPCION_B":"Las cinturas escapular y pélvica y los huesos de las extremidades.","OPCION_C":"El encéfalo, además de sostener estructuras de la cara.","OPCION_D":"Cráneo, columna vertebral y caja torácica.","RESPUESTA_CORRECTA":"D","EXPLICACION":"Cráneo, columna vertebral y caja torácica.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"261–305"},{"MATERIA":"MORFOFUNCION","TEMA":"el sistema oseo","DIFICULTAD":"facil","PREGUNTA":"¿Qué incluye el esqueleto apendicular?","OPCION_A":"El encéfalo, además de sostener estructuras de la cara.","OPCION_B":"Cráneo, columna vertebral y caja torácica.","OPCION_C":"El paso de corriente entre cardiocitos para propagar la excitación.","OPCION_D":"Las cinturas escapular y pélvica y los huesos de las extremidades.","RESPUESTA_CORRECTA":"D","EXPLICACION":"Las cinturas escapular y pélvica y los huesos de las extremidades.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"261–305"},{"MATERIA":"MORFOFUNCION","TEMA":"el sistema oseo","DIFICULTAD":"facil","PREGUNTA":"¿Qué protege principalmente el cráneo?","OPCION_A":"Las cinturas escapular y pélvica y los huesos de las extremidades.","OPCION_B":"El cierre de las válvulas semilunares al terminar la eyección.","OPCION_C":"El encéfalo, además de sostener estructuras de la cara.","OPCION_D":"Cráneo, columna vertebral y caja torácica.","RESPUESTA_CORRECTA":"C","EXPLICACION":"El encéfalo, además de sostener estructuras de la cara.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"261–305"},{"MATERIA":"MORFOFUNCION","TEMA":"el sistema oseo","DIFICULTAD":"medio","PREGUNTA":"Si observas el cuerpo alargado de un hueso largo, ¿cómo se llama esa región?","OPCION_A":"Cráneo, columna vertebral y caja torácica.","OPCION_B":"Más agudo.","OPCION_C":"Disminuye.","OPCION_D":"Diáfisis.","RESPUESTA_CORRECTA":"D","EXPLICACION":"Diáfisis.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"261–305"},{"MATERIA":"MORFOFUNCION","TEMA":"articulaciones","DIFICULTAD":"facil","PREGUNTA":"Una articulación permite mucho movimiento y contiene una cavidad con líquido. ¿De qué tipo es?","OPCION_A":"Reduce la fricción y ayuda a repartir las cargas entre las superficies óseas.","OPCION_B":"Sinovial.","OPCION_C":"Un ligamento.","OPCION_D":"Nefrona.","RESPUESTA_CORRECTA":"B","EXPLICACION":"Sinovial.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"306–339"},{"MATERIA":"MORFOFUNCION","TEMA":"articulaciones","DIFICULTAD":"facil","PREGUNTA":"¿Qué estructura une un hueso con otro y ayuda a estabilizar la articulación?","OPCION_A":"La sutura es una articulación fibrosa con muy poco movimiento; la rodilla es sinovial y móvil.","OPCION_B":"La histamina.","OPCION_C":"El osteoclasto.","OPCION_D":"Un ligamento.","RESPUESTA_CORRECTA":"D","EXPLICACION":"Un ligamento.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"306–339"},{"MATERIA":"MORFOFUNCION","TEMA":"articulaciones","DIFICULTAD":"medio","PREGUNTA":"¿Para qué sirve el cartílago articular en una articulación sinovial?","OPCION_A":"Sinovial.","OPCION_B":"Reduce la tensión superficial y ayuda a que no colapsen al espirar.","OPCION_C":"Reduce la fricción y ayuda a repartir las cargas entre las superficies óseas.","OPCION_D":"Une y lubrica las partículas de alimento para facilitar la deglución.","RESPUESTA_CORRECTA":"C","EXPLICACION":"Reduce la fricción y ayuda a repartir las cargas entre las superficies óseas.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"306–339"},{"MATERIA":"MORFOFUNCION","TEMA":"articulaciones","DIFICULTAD":"dificil","PREGUNTA":"¿Qué diferencia básica hay entre una sutura craneal y una rodilla?","OPCION_A":"Un ligamento.","OPCION_B":"La sutura es una articulación fibrosa con muy poco movimiento; la rodilla es sinovial y móvil.","OPCION_C":"La conductora lleva y acondiciona aire; la respiratoria contiene alvéolos e intercambia gases.","OPCION_D":"El esófago tiene epitelio estratificado protector; el estómago, epitelio cilíndrico secretor.","RESPUESTA_CORRECTA":"B","EXPLICACION":"La sutura es una articulación fibrosa con muy poco movimiento; la rodilla es sinovial y móvil.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"306–339"},{"MATERIA":"MORFOFUNCION","TEMA":"el sistema muscular","DIFICULTAD":"facil","PREGUNTA":"Cuando flexionas el codo, ¿cómo se llama el músculo que produce principalmente ese movimiento?","OPCION_A":"Fascículo.","OPCION_B":"Agonista o motor principal.","OPCION_C":"Aumenta hasta acercarse a su capacidad máxima.","OPCION_D":"Circulación enterohepática.","RESPUESTA_CORRECTA":"B","EXPLICACION":"Agonista o motor principal.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"340–428"},{"MATERIA":"MORFOFUNCION","TEMA":"el sistema muscular","DIFICULTAD":"facil","PREGUNTA":"¿Qué hace un músculo antagonista durante un movimiento?","OPCION_A":"Se opone o controla la acción del agonista y permite el movimiento contrario.","OPCION_B":"La inserción suele ser el extremo más móvil.","OPCION_C":"Que ambas superficies se deslicen con poco rozamiento durante la respiración.","OPCION_D":"Que la energía ingerida se aproxima a la energía gastada durante un período.","RESPUESTA_CORRECTA":"A","EXPLICACION":"Se opone o controla la acción del agonista y permite el movimiento contrario.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"340–428"},{"MATERIA":"MORFOFUNCION","TEMA":"el sistema muscular","DIFICULTAD":"facil","PREGUNTA":"¿Cómo se llama un conjunto de fibras musculares agrupadas dentro de un músculo?","OPCION_A":"Fascículo.","OPCION_B":"Agonista o motor principal.","OPCION_C":"Osteocito.","OPCION_D":"Diástole.","RESPUESTA_CORRECTA":"A","EXPLICACION":"Fascículo.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"340–428"},{"MATERIA":"MORFOFUNCION","TEMA":"el sistema muscular","DIFICULTAD":"facil","PREGUNTA":"¿Qué extremo de un músculo suele moverse más durante una contracción: origen o inserción?","OPCION_A":"Un esfínter que regula el paso del contenido.","OPCION_B":"La inserción suele ser el extremo más móvil.","OPCION_C":"Se opone o controla la acción del agonista y permite el movimiento contrario.","OPCION_D":"Los macrófagos hepáticos o células de Kupffer.","RESPUESTA_CORRECTA":"B","EXPLICACION":"La inserción suele ser el extremo más móvil.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"340–428"},{"MATERIA":"MORFOFUNCION","TEMA":"tejido muscular","DIFICULTAD":"facil","PREGUNTA":"¿Cuál es la unidad contráctil que se acorta dentro de una miofibrilla?","OPCION_A":"El sarcómero.","OPCION_B":"El calcio; al unirse a troponina deja disponibles los sitios de unión de actina.","OPCION_C":"El alvéolo.","OPCION_D":"El duodeno.","RESPUESTA_CORRECTA":"A","EXPLICACION":"El sarcómero.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"429–466"},{"MATERIA":"MORFOFUNCION","TEMA":"tejido muscular","DIFICULTAD":"facil","PREGUNTA":"¿Qué ion permite que actina y miosina inicien la contracción del músculo estriado?","OPCION_A":"El sarcómero.","OPCION_B":"La onda de presión generada por la eyección de sangre hacia la aorta.","OPCION_C":"Los ácidos biliares, que participan en la emulsificación y formación de micelas.","OPCION_D":"El calcio; al unirse a troponina deja disponibles los sitios de unión de actina.","RESPUESTA_CORRECTA":"D","EXPLICACION":"El calcio; al unirse a troponina deja disponibles los sitios de unión de actina.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"429–466"},{"MATERIA":"MORFOFUNCION","TEMA":"tejido muscular","DIFICULTAD":"facil","PREGUNTA":"¿Para qué necesita ATP el ciclo de puentes entre actina y miosina?","OPCION_A":"Músculo liso.","OPCION_B":"Entre otras funciones, para separar la cabeza de miosina de la actina y preparar un nuevo ciclo.","OPCION_C":"Conectan sus valvas con los músculos papilares y evitan que se inviertan durante la contracción.","OPCION_D":"Permite que las aurículas terminen de vaciarse antes de que se contraigan los ventrículos.","RESPUESTA_CORRECTA":"B","EXPLICACION":"Entre otras funciones, para separar la cabeza de miosina de la actina y preparar un nuevo ciclo.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"429–466"},{"MATERIA":"MORFOFUNCION","TEMA":"tejido muscular","DIFICULTAD":"facil","PREGUNTA":"¿Qué tipo de músculo forma la pared del intestino y se contrae de modo involuntario?","OPCION_A":"Entre otras funciones, para separar la cabeza de miosina de la actina y preparar un nuevo ciclo.","OPCION_B":"Músculo liso.","OPCION_C":"Tiende a aumentarla.","OPCION_D":"Tiende a disminuirla.","RESPUESTA_CORRECTA":"B","EXPLICACION":"Músculo liso.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"429–466"},{"MATERIA":"MORFOFUNCION","TEMA":"tejido nervioso","DIFICULTAD":"facil","PREGUNTA":"¿Qué parte de una neurona suele recibir señales de otras células?","OPCION_A":"El pericardio.","OPCION_B":"Las dendritas.","OPCION_C":"Las plaquetas.","OPCION_D":"El endometrio.","RESPUESTA_CORRECTA":"B","EXPLICACION":"Las dendritas.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"467–505"},{"MATERIA":"MORFOFUNCION","TEMA":"tejido nervioso","DIFICULTAD":"dificil","PREGUNTA":"¿Por qué la mielina acelera la conducción en muchos axones?","OPCION_A":"Porque el hueso almacena y libera minerales, especialmente calcio y fosfato.","OPCION_B":"Porque el corazón ocupa parte del lado izquierdo del mediastino.","OPCION_C":"Porque el impulso se regenera principalmente en los nodos de Ranvier y salta entre ellos.","OPCION_D":"Porque debe reducir el volumen torácico con más fuerza que el retroceso elástico normal.","RESPUESTA_CORRECTA":"C","EXPLICACION":"Porque el impulso se regenera principalmente en los nodos de Ranvier y salta entre ellos.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"467–505"},{"MATERIA":"MORFOFUNCION","TEMA":"tejido nervioso","DIFICULTAD":"facil","PREGUNTA":"¿Cómo se llama la unión funcional donde una neurona transmite información a otra célula?","OPCION_A":"Entra Na+ y la membrana se despolariza rápidamente.","OPCION_B":"Sinapsis.","OPCION_C":"Nefrona.","OPCION_D":"Diástole.","RESPUESTA_CORRECTA":"B","EXPLICACION":"Sinapsis.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"467–505"},{"MATERIA":"MORFOFUNCION","TEMA":"tejido nervioso","DIFICULTAD":"facil","PREGUNTA":"¿Qué ocurre al inicio de un potencial de acción típico cuando se abren canales de sodio dependientes de voltaje?","OPCION_A":"Entra Na+ y la membrana se despolariza rápidamente.","OPCION_B":"Sinapsis.","OPCION_C":"Sangre venosa procedente de las arterias pulmonares.","OPCION_D":"Disminuye y el aire puede entrar desde la atmósfera.","RESPUESTA_CORRECTA":"A","EXPLICACION":"Entra Na+ y la membrana se despolariza rápidamente.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"467–505"},{"MATERIA":"MORFOFUNCION","TEMA":"medula espinal y reflejos","DIFICULTAD":"dificil","PREGUNTA":"¿Por qué raíz entra la información sensitiva a la médula espinal?","OPCION_A":"Por la raíz ventral o anterior.","OPCION_B":"Por la raíz dorsal o posterior.","OPCION_C":"Por la válvula pulmonar.","OPCION_D":"Por la válvula aórtica.","RESPUESTA_CORRECTA":"B","EXPLICACION":"Por la raíz dorsal o posterior.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"506–538"},{"MATERIA":"MORFOFUNCION","TEMA":"medula espinal y reflejos","DIFICULTAD":"dificil","PREGUNTA":"¿Por qué raíz salen las fibras motoras de un nervio raquídeo?","OPCION_A":"Por la raíz dorsal o posterior.","OPCION_B":"Por la raíz ventral o anterior.","OPCION_C":"Por la válvula pulmonar.","OPCION_D":"Por la válvula aórtica.","RESPUESTA_CORRECTA":"B","EXPLICACION":"Por la raíz ventral o anterior.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"506–538"},{"MATERIA":"MORFOFUNCION","TEMA":"medula espinal y reflejos","DIFICULTAD":"facil","PREGUNTA":"Tocas algo muy caliente y retiras la mano antes de pensarlo. ¿Qué circuito lo explica?","OPCION_A":"La gris ocupa la zona central; la blanca la rodea.","OPCION_B":"La conductora lleva y acondiciona aire; la respiratoria contiene alvéolos e intercambia gases.","OPCION_C":"Un arco reflejo medular, que integra una respuesta rápida sin esperar una decisión consciente.","OPCION_D":"La sutura es una articulación fibrosa con muy poco movimiento; la rodilla es sinovial y móvil.","RESPUESTA_CORRECTA":"C","EXPLICACION":"Un arco reflejo medular, que integra una respuesta rápida sin esperar una decisión consciente.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"506–538"},{"MATERIA":"MORFOFUNCION","TEMA":"medula espinal y reflejos","DIFICULTAD":"facil","PREGUNTA":"En un corte medular, ¿dónde se sitúa la sustancia gris respecto de la blanca?","OPCION_A":"Un arco reflejo medular, que integra una respuesta rápida sin esperar una decisión consciente.","OPCION_B":"La gris ocupa la zona central; la blanca la rodea.","OPCION_C":"La despolarización de los ventrículos.","OPCION_D":"La repolarización de los ventrículos.","RESPUESTA_CORRECTA":"B","EXPLICACION":"La gris ocupa la zona central; la blanca la rodea.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"506–538"},{"MATERIA":"MORFOFUNCION","TEMA":"encefalo y pares craneales","DIFICULTAD":"facil","PREGUNTA":"¿Qué parte del encéfalo afina la coordinación y el equilibrio de los movimientos?","OPCION_A":"El cerebelo.","OPCION_B":"El bulbo raquídeo.","OPCION_C":"El líquido cefalorraquídeo.","OPCION_D":"La placenta.","RESPUESTA_CORRECTA":"A","EXPLICACION":"El cerebelo.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"539–588"},{"MATERIA":"MORFOFUNCION","TEMA":"encefalo y pares craneales","DIFICULTAD":"facil","PREGUNTA":"¿Qué estructura del tronco encefálico contiene centros vitales relacionados con respiración y circulación?","OPCION_A":"El cerebelo.","OPCION_B":"El bulbo raquídeo.","OPCION_C":"El líquido cefalorraquídeo.","OPCION_D":"El folículo ovárico.","RESPUESTA_CORRECTA":"B","EXPLICACION":"El bulbo raquídeo.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"539–588"},{"MATERIA":"MORFOFUNCION","TEMA":"encefalo y pares craneales","DIFICULTAD":"facil","PREGUNTA":"¿Qué papel cumple el tálamo para muchas señales sensitivas?","OPCION_A":"Actúa como estación de relevo antes de que lleguen a la corteza cerebral.","OPCION_B":"Disminuyen la energía de activación necesaria para que la reacción ocurra.","OPCION_C":"Aumenta la presión con todas las válvulas cerradas y sin cambio de volumen.","OPCION_D":"Componentes de los discos intercalares, como desmosomas y fascia adherente.","RESPUESTA_CORRECTA":"A","EXPLICACION":"Actúa como estación de relevo antes de que lleguen a la corteza cerebral.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"539–588"},{"MATERIA":"MORFOFUNCION","TEMA":"encefalo y pares craneales","DIFICULTAD":"facil","PREGUNTA":"¿Qué líquido circula por los ventrículos y alrededor del encéfalo y la médula?","OPCION_A":"El bulbo raquídeo.","OPCION_B":"El líquido cefalorraquídeo.","OPCION_C":"El cerebelo.","OPCION_D":"El tabique interventricular.","RESPUESTA_CORRECTA":"B","EXPLICACION":"El líquido cefalorraquídeo.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"539–588"},{"MATERIA":"MORFOFUNCION","TEMA":"sistema nervioso autonomo","DIFICULTAD":"facil","PREGUNTA":"En una situación de alerta, ¿qué división autónoma suele elevar la frecuencia cardiaca?","OPCION_A":"La parasimpática.","OPCION_B":"La simpática.","OPCION_C":"Una respuesta automática de un órgano interno ante un estímulo, coordinada por circuitos del sistema nervioso autónomo.","OPCION_D":"El osteoblasto.","RESPUESTA_CORRECTA":"B","EXPLICACION":"La simpática.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"589–609"},{"MATERIA":"MORFOFUNCION","TEMA":"sistema nervioso autonomo","DIFICULTAD":"facil","PREGUNTA":"Después de comer, ¿qué división favorece la digestión y el reposo?","OPCION_A":"La simpática.","OPCION_B":"Una respuesta automática de un órgano interno ante un estímulo, coordinada por circuitos del sistema nervioso autónomo.","OPCION_C":"Los bronquios segmentarios.","OPCION_D":"La parasimpática.","RESPUESTA_CORRECTA":"D","EXPLICACION":"La parasimpática.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"589–609"},{"MATERIA":"MORFOFUNCION","TEMA":"sistema nervioso autonomo","DIFICULTAD":"facil","PREGUNTA":"¿Cuántas neuronas motoras suelen intervenir entre el sistema nervioso central y un órgano visceral?","OPCION_A":"Dos: una preganglionar y otra posganglionar, conectadas en un ganglio.","OPCION_B":"Tres: oblicua interna, circular media y longitudinal externa.","OPCION_C":"Hasta cuatro, una en cada grupo hemo.","OPCION_D":"De anatomía. La fisiología se ocupa de cómo funciona ese órgano.","RESPUESTA_CORRECTA":"A","EXPLICACION":"Dos: una preganglionar y otra posganglionar, conectadas en un ganglio.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"589–609"},{"MATERIA":"MORFOFUNCION","TEMA":"sistema nervioso autonomo","DIFICULTAD":"facil","PREGUNTA":"¿Qué es un reflejo visceral?","OPCION_A":"La parasimpática.","OPCION_B":"La simpática.","OPCION_C":"La exocrina vierte su producto por conductos; la endocrina libera hormonas al líquido intersticial y la sangre.","OPCION_D":"Una respuesta automática de un órgano interno ante un estímulo, coordinada por circuitos del sistema nervioso autónomo.","RESPUESTA_CORRECTA":"D","EXPLICACION":"Una respuesta automática de un órgano interno ante un estímulo, coordinada por circuitos del sistema nervioso autónomo.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"589–609"},{"MATERIA":"MORFOFUNCION","TEMA":"organos de los sentidos","DIFICULTAD":"medio","PREGUNTA":"Si un receptor responde a presión sobre la piel, ¿qué tipo de estímulo detecta?","OPCION_A":"El aparato vestibular, que incluye conductos semicirculares y órganos otolíticos.","OPCION_B":"Los nociceptores.","OPCION_C":"Los bastones.","OPCION_D":"Un estímulo mecánico; es un mecanorreceptor.","RESPUESTA_CORRECTA":"D","EXPLICACION":"Un estímulo mecánico; es un mecanorreceptor.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"610–660"},{"MATERIA":"MORFOFUNCION","TEMA":"organos de los sentidos","DIFICULTAD":"facil","PREGUNTA":"¿Qué receptores advierten daño real o posible y participan en la percepción del dolor?","OPCION_A":"Los nociceptores.","OPCION_B":"Los bastones.","OPCION_C":"Los conos.","OPCION_D":"El aparato vestibular, que incluye conductos semicirculares y órganos otolíticos.","RESPUESTA_CORRECTA":"A","EXPLICACION":"Los nociceptores.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"610–660"},{"MATERIA":"MORFOFUNCION","TEMA":"organos de los sentidos","DIFICULTAD":"dificil","PREGUNTA":"¿Por qué gusto y olfato se consideran sentidos químicos?","OPCION_A":"Porque sus células generan impulsos espontáneos que normalmente fijan el ritmo.","OPCION_B":"Para mantener el flujo de sangre en una sola dirección.","OPCION_C":"Porque suele expulsar más sangre en cada latido.","OPCION_D":"Porque sus receptores responden a moléculas químicas.","RESPUESTA_CORRECTA":"D","EXPLICACION":"Porque sus receptores responden a moléculas químicas.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"610–660"},{"MATERIA":"MORFOFUNCION","TEMA":"organos de los sentidos","DIFICULTAD":"facil","PREGUNTA":"¿Qué estructura del oído interno detecta el movimiento de la cabeza para el equilibrio?","OPCION_A":"Un estímulo mecánico; es un mecanorreceptor.","OPCION_B":"Los nociceptores.","OPCION_C":"Los bastones.","OPCION_D":"El aparato vestibular, que incluye conductos semicirculares y órganos otolíticos.","RESPUESTA_CORRECTA":"D","EXPLICACION":"El aparato vestibular, que incluye conductos semicirculares y órganos otolíticos.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"610–660"},{"MATERIA":"MORFOFUNCION","TEMA":"organos de los sentidos","DIFICULTAD":"facil","PREGUNTA":"¿Qué células de la retina permiten ver mejor con poca luz?","OPCION_A":"Los conos.","OPCION_B":"Los nociceptores.","OPCION_C":"El aparato vestibular, que incluye conductos semicirculares y órganos otolíticos.","OPCION_D":"Los bastones.","RESPUESTA_CORRECTA":"D","EXPLICACION":"Los bastones.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"610–660"},{"MATERIA":"MORFOFUNCION","TEMA":"organos de los sentidos","DIFICULTAD":"facil","PREGUNTA":"¿Qué células de la retina aportan visión de color y gran detalle?","OPCION_A":"Los conos.","OPCION_B":"Los bastones.","OPCION_C":"Los nociceptores.","OPCION_D":"El aparato vestibular, que incluye conductos semicirculares y órganos otolíticos.","RESPUESTA_CORRECTA":"A","EXPLICACION":"Los conos.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"610–660"},{"MATERIA":"MORFOFUNCION","TEMA":"sistema endocrino","DIFICULTAD":"facil","PREGUNTA":"¿Cómo llegan las hormonas de una glándula endocrina a órganos lejanos?","OPCION_A":"La exocrina vierte su producto por conductos; la endocrina libera hormonas al líquido intersticial y la sangre.","OPCION_B":"Se liberan a la sangre y viajan hasta células con receptores adecuados.","OPCION_C":"Que una sustancia pasa del filtrado de la nefrona de vuelta a la sangre.","OPCION_D":"Que el estímulo inicial del latido surge en el propio tejido cardiaco.","RESPUESTA_CORRECTA":"B","EXPLICACION":"Se liberan a la sangre y viajan hasta células con receptores adecuados.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"661–705"},{"MATERIA":"MORFOFUNCION","TEMA":"sistema endocrino","DIFICULTAD":"dificil","PREGUNTA":"¿Qué diferencia a una glándula exocrina de una endocrina?","OPCION_A":"El glucagón.","OPCION_B":"La insulina.","OPCION_C":"La isquemia es aporte insuficiente de sangre; el infarto implica muerte de tejido por una isquemia mantenida.","OPCION_D":"La exocrina vierte su producto por conductos; la endocrina libera hormonas al líquido intersticial y la sangre.","RESPUESTA_CORRECTA":"D","EXPLICACION":"La exocrina vierte su producto por conductos; la endocrina libera hormonas al líquido intersticial y la sangre.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"661–705"},{"MATERIA":"MORFOFUNCION","TEMA":"sistema endocrino","DIFICULTAD":"facil","PREGUNTA":"Tras una comida sube la glucosa. ¿Qué hormona pancreática favorece su descenso?","OPCION_A":"La insulina.","OPCION_B":"El glucagón.","OPCION_C":"La exocrina vierte su producto por conductos; la endocrina libera hormonas al líquido intersticial y la sangre.","OPCION_D":"La secretina.","RESPUESTA_CORRECTA":"A","EXPLICACION":"La insulina.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"661–705"},{"MATERIA":"MORFOFUNCION","TEMA":"sistema endocrino","DIFICULTAD":"medio","PREGUNTA":"Si baja la glucosa entre comidas, ¿qué hormona pancreática ayuda a elevarla?","OPCION_A":"La insulina.","OPCION_B":"La exocrina vierte su producto por conductos; la endocrina libera hormonas al líquido intersticial y la sangre.","OPCION_C":"El glucagón.","OPCION_D":"La progesterona.","RESPUESTA_CORRECTA":"C","EXPLICACION":"El glucagón.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"661–705"},{"MATERIA":"MORFOFUNCION","TEMA":"sangre","DIFICULTAD":"facil","PREGUNTA":"¿Qué componente líquido de la sangre transporta solutos y proteínas?","OPCION_A":"El plasma.","OPCION_B":"Las plaquetas.","OPCION_C":"Los leucocitos o glóbulos blancos.","OPCION_D":"El derecho.","RESPUESTA_CORRECTA":"A","EXPLICACION":"El plasma.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"706–741"},{"MATERIA":"MORFOFUNCION","TEMA":"sangre","DIFICULTAD":"facil","PREGUNTA":"¿Qué llevan principalmente los eritrocitos gracias a la hemoglobina?","OPCION_A":"Oxígeno desde los pulmones hacia los tejidos.","OPCION_B":"Los leucocitos o glóbulos blancos.","OPCION_C":"Agua y sales, con lo que ayuda a formar las heces.","OPCION_D":"Vasos sanguíneos, vasos linfáticos y nervios.","RESPUESTA_CORRECTA":"A","EXPLICACION":"Oxígeno desde los pulmones hacia los tejidos.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"706–741"},{"MATERIA":"MORFOFUNCION","TEMA":"sangre","DIFICULTAD":"facil","PREGUNTA":"¿Qué células sanguíneas participan de manera importante en la defensa del organismo?","OPCION_A":"Las plaquetas.","OPCION_B":"El plasma.","OPCION_C":"La defensa innata o inespecífica.","OPCION_D":"Los leucocitos o glóbulos blancos.","RESPUESTA_CORRECTA":"D","EXPLICACION":"Los leucocitos o glóbulos blancos.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"706–741"},{"MATERIA":"MORFOFUNCION","TEMA":"sangre","DIFICULTAD":"facil","PREGUNTA":"¿Qué fragmentos celulares ayudan a formar el tapón inicial cuando se lesiona un vaso?","OPCION_A":"El plasma.","OPCION_B":"Las plaquetas.","OPCION_C":"Los leucocitos o glóbulos blancos.","OPCION_D":"El endometrio.","RESPUESTA_CORRECTA":"B","EXPLICACION":"Las plaquetas.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"706–741"},{"MATERIA":"MORFOFUNCION","TEMA":"corazon","DIFICULTAD":"facil","PREGUNTA":"¿A dónde envía sangre el circuito pulmonar desde el lado derecho del corazón?","OPCION_A":"Insuficiencia o regurgitación valvular.","OPCION_B":"Tricúspide, pulmonar, mitral y aórtica.","OPCION_C":"A los pulmones para el intercambio de gases.","OPCION_D":"Durante la diástole, cuando el miocardio se relaja.","RESPUESTA_CORRECTA":"C","EXPLICACION":"A los pulmones para el intercambio de gases.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"742–776"},{"MATERIA":"MORFOFUNCION","TEMA":"corazon","DIFICULTAD":"facil","PREGUNTA":"¿Qué evita que la sangre retroceda dentro del corazón cuando cambia la presión?","OPCION_A":"La circulación pulmonar.","OPCION_B":"El ventrículo izquierdo.","OPCION_C":"Las válvulas cardíacas.","OPCION_D":"La circulación sistémica.","RESPUESTA_CORRECTA":"C","EXPLICACION":"Las válvulas cardíacas.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"742–776"},{"MATERIA":"MORFOFUNCION","TEMA":"corazon","DIFICULTAD":"facil","PREGUNTA":"¿Qué estructura inicia normalmente cada latido como marcapasos del corazón?","OPCION_A":"El nódulo sinoauricular, o SA.","OPCION_B":"Las válvulas cardíacas.","OPCION_C":"El nodo sinoauricular.","OPCION_D":"La circulación pulmonar.","RESPUESTA_CORRECTA":"C","EXPLICACION":"El nodo sinoauricular.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"742–776"},{"MATERIA":"MORFOFUNCION","TEMA":"corazon","DIFICULTAD":"facil","PREGUNTA":"¿Qué cavidad impulsa sangre hacia la circulación sistémica?","OPCION_A":"El ventrículo derecho.","OPCION_B":"La circulación sistémica.","OPCION_C":"Las arterias coronarias.","OPCION_D":"El ventrículo izquierdo.","RESPUESTA_CORRECTA":"D","EXPLICACION":"El ventrículo izquierdo.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"742–776"},{"MATERIA":"MORFOFUNCION","TEMA":"vasos sanguineos y circulacion","DIFICULTAD":"dificil","PREGUNTA":"¿Qué diferencia básica hay entre arterias y venas según la dirección del flujo?","OPCION_A":"Las arterias y venas mayores que entran y salen del corazón.","OPCION_B":"Las arterias coronarias.","OPCION_C":"Las arterias llevan sangre desde el corazón; las venas la devuelven al corazón.","OPCION_D":"La sutura es una articulación fibrosa con muy poco movimiento; la rodilla es sinovial y móvil.","RESPUESTA_CORRECTA":"C","EXPLICACION":"Las arterias llevan sangre desde el corazón; las venas la devuelven al corazón.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"777–835"},{"MATERIA":"MORFOFUNCION","TEMA":"vasos sanguineos y circulacion","DIFICULTAD":"facil","PREGUNTA":"¿En qué vasos ocurre la mayor parte del intercambio con los tejidos?","OPCION_A":"En los bronquios principales derecho e izquierdo.","OPCION_B":"En los túbulos seminíferos de los testículos.","OPCION_C":"En los canalículos biliares.","OPCION_D":"En los capilares, por sus paredes muy delgadas.","RESPUESTA_CORRECTA":"D","EXPLICACION":"En los capilares, por sus paredes muy delgadas.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"777–835"},{"MATERIA":"MORFOFUNCION","TEMA":"vasos sanguineos y circulacion","DIFICULTAD":"dificil","PREGUNTA":"¿Por qué muchas venas de las extremidades tienen válvulas?","OPCION_A":"Para que oxígeno y dióxido de carbono difundan a corta distancia.","OPCION_B":"Porque la contracción cambia presiones y esas diferencias abren o cierran las válvulas.","OPCION_C":"Para dificultar el retroceso de la sangre mientras retorna al corazón.","OPCION_D":"Para mantener el flujo de sangre en una sola dirección.","RESPUESTA_CORRECTA":"C","EXPLICACION":"Para dificultar el retroceso de la sangre mientras retorna al corazón.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"777–835"},{"MATERIA":"MORFOFUNCION","TEMA":"vasos sanguineos y circulacion","DIFICULTAD":"medio","PREGUNTA":"Si una arteriola se estrecha, ¿qué ocurre con la resistencia al paso de la sangre?","OPCION_A":"Estenosis valvular.","OPCION_B":"Aumenta la fuerza de contracción y el volumen expulsado.","OPCION_C":"Aumenta la resistencia vascular.","OPCION_D":"Insuficiencia o regurgitación valvular.","RESPUESTA_CORRECTA":"C","EXPLICACION":"Aumenta la resistencia vascular.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"777–835"},{"MATERIA":"MORFOFUNCION","TEMA":"sistema linfatico e inmunidad","DIFICULTAD":"facil","PREGUNTA":"¿Qué pasa con el líquido intersticial que recogen los vasos linfáticos?","OPCION_A":"La filtran y facilitan el encuentro de células inmunitarias con antígenos.","OPCION_B":"Que ambas superficies se deslicen con poco rozamiento durante la respiración.","OPCION_C":"Que el estímulo inicial del latido surge en el propio tejido cardiaco.","OPCION_D":"Se convierte en linfa y acaba regresando a la circulación sanguínea.","RESPUESTA_CORRECTA":"D","EXPLICACION":"Se convierte en linfa y acaba regresando a la circulación sanguínea.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"836–881"},{"MATERIA":"MORFOFUNCION","TEMA":"sistema linfatico e inmunidad","DIFICULTAD":"facil","PREGUNTA":"¿Qué función tienen los ganglios linfáticos en el trayecto de la linfa?","OPCION_A":"La defensa innata o inespecífica.","OPCION_B":"La filtran y facilitan el encuentro de células inmunitarias con antígenos.","OPCION_C":"El bazo.","OPCION_D":"Se convierte en linfa y acaba regresando a la circulación sanguínea.","RESPUESTA_CORRECTA":"B","EXPLICACION":"La filtran y facilitan el encuentro de células inmunitarias con antígenos.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"836–881"},{"MATERIA":"MORFOFUNCION","TEMA":"sistema linfatico e inmunidad","DIFICULTAD":"facil","PREGUNTA":"¿Qué tipo de defensa actúa rápido y sin reconocer un antígeno concreto?","OPCION_A":"La filtran y facilitan el encuentro de células inmunitarias con antígenos.","OPCION_B":"El bazo.","OPCION_C":"Los leucocitos o glóbulos blancos.","OPCION_D":"La defensa innata o inespecífica.","RESPUESTA_CORRECTA":"D","EXPLICACION":"La defensa innata o inespecífica.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"836–881"},{"MATERIA":"MORFOFUNCION","TEMA":"sistema linfatico e inmunidad","DIFICULTAD":"facil","PREGUNTA":"¿Qué órgano filtra sangre y participa en respuestas inmunitarias frente a antígenos sanguíneos?","OPCION_A":"La defensa innata o inespecífica.","OPCION_B":"La filtran y facilitan el encuentro de células inmunitarias con antígenos.","OPCION_C":"El bazo.","OPCION_D":"El plasma.","RESPUESTA_CORRECTA":"C","EXPLICACION":"El bazo.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"836–881"},{"MATERIA":"MORFOFUNCION","TEMA":"aparato respiratorio","DIFICULTAD":"facil","PREGUNTA":"Al inspirar tranquilamente, ¿qué músculo aumenta el volumen del tórax al contraerse?","OPCION_A":"El diafragma.","OPCION_B":"El izquierdo.","OPCION_C":"La tráquea.","OPCION_D":"El alvéolo.","RESPUESTA_CORRECTA":"A","EXPLICACION":"El diafragma.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"882–922"},{"MATERIA":"MORFOFUNCION","TEMA":"aparato respiratorio","DIFICULTAD":"facil","PREGUNTA":"¿Dónde difunden oxígeno y dióxido de carbono entre el aire y la sangre?","OPCION_A":"En el bulbo raquídeo y la protuberancia del tronco encefálico.","OPCION_B":"En los bronquios principales derecho e izquierdo.","OPCION_C":"En la membrana respiratoria de los alvéolos y sus capilares.","OPCION_D":"Hacia fuera del pulmón.","RESPUESTA_CORRECTA":"C","EXPLICACION":"En la membrana respiratoria de los alvéolos y sus capilares.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"882–922"},{"MATERIA":"MORFOFUNCION","TEMA":"aparato respiratorio","DIFICULTAD":"facil","PREGUNTA":"¿Qué tubo conduce aire desde la laringe hacia los bronquios?","OPCION_A":"El izquierdo.","OPCION_B":"El asma.","OPCION_C":"La tráquea.","OPCION_D":"El cartílago tiroides.","RESPUESTA_CORRECTA":"C","EXPLICACION":"La tráquea.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"882–922"},{"MATERIA":"MORFOFUNCION","TEMA":"aparato respiratorio","DIFICULTAD":"facil","PREGUNTA":"¿Qué recubre los pulmones y ayuda a que se deslicen contra la pared torácica?","OPCION_A":"La pleura, con sus hojas visceral y parietal y una fina película de líquido entre ellas.","OPCION_B":"Las reacciones se invierten, se libera CO2 y difunde hacia los alvéolos.","OPCION_C":"El volumen de aire que queda en vías conductoras y no llega a zonas de intercambio.","OPCION_D":"La conductora lleva y acondiciona aire; la respiratoria contiene alvéolos e intercambia gases.","RESPUESTA_CORRECTA":"A","EXPLICACION":"La pleura, con sus hojas visceral y parietal y una fina película de líquido entre ellas.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"882–922"},{"MATERIA":"MORFOFUNCION","TEMA":"aparato urinario","DIFICULTAD":"facil","PREGUNTA":"¿Cómo se llama la unidad funcional del riñón que filtra y modifica el líquido tubular?","OPCION_A":"Sinapsis.","OPCION_B":"Nefrona.","OPCION_C":"Sístole.","OPCION_D":"Diástole.","RESPUESTA_CORRECTA":"B","EXPLICACION":"Nefrona.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"923–957"},{"MATERIA":"MORFOFUNCION","TEMA":"aparato urinario","DIFICULTAD":"facil","PREGUNTA":"¿Qué ocurre primero con el plasma cuando atraviesa el glomérulo renal?","OPCION_A":"Que una sustancia pasa del filtrado de la nefrona de vuelta a la sangre.","OPCION_B":"Que el contenido del intestino grueso retroceda hacia el íleon.","OPCION_C":"Se filtra parte de su agua y solutos hacia la cápsula glomerular.","OPCION_D":"Que la sangre del tronco pulmonar vuelva al ventrículo derecho.","RESPUESTA_CORRECTA":"C","EXPLICACION":"Se filtra parte de su agua y solutos hacia la cápsula glomerular.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"923–957"}]'::jsonb) AS p("MATERIA" text, "TEMA" text, "DIFICULTAD" text, "PREGUNTA" text, "OPCION_A" text, "OPCION_B" text, "OPCION_C" text, "OPCION_D" text, "RESPUESTA_CORRECTA" text, "EXPLICACION" text, "FUENTE" text, "PAGINAS_PDF" text)
), missing AS (
  SELECT p.* FROM payload p
  WHERE NOT EXISTS (
    SELECT 1 FROM public.banco_preguntas b
    WHERE b."MATERIA" = p."MATERIA" AND lower(b."PREGUNTA") = lower(p."PREGUNTA")
  )
), numbered AS (
  SELECT (SELECT coalesce(max(id), 0) FROM public.banco_preguntas) + row_number() OVER (ORDER BY "MATERIA", "TEMA", "PREGUNTA") AS id, m.*
  FROM missing m
)
INSERT INTO public.banco_preguntas (id, "MATERIA", "TEMA", "DIFICULTAD", "PREGUNTA", "OPCION_A", "OPCION_B", "OPCION_C", "OPCION_D", "RESPUESTA_CORRECTA", "EXPLICACION", "FUENTE", "PAGINAS_PDF")
SELECT n.id, n."MATERIA", n."TEMA", n."DIFICULTAD", n."PREGUNTA", n."OPCION_A", n."OPCION_B", n."OPCION_C", n."OPCION_D", n."RESPUESTA_CORRECTA", n."EXPLICACION", n."FUENTE", n."PAGINAS_PDF" FROM numbered n;
COMMIT;

-- Banco de preguntas oficial, lote 15. Reejecutable sin duplicados.
