WITH payload AS (
  SELECT * FROM jsonb_to_recordset('[{"MATERIA":"MORFOFUNCION","TEMA":"aparato urinario","DIFICULTAD":"facil","PREGUNTA":"¿Qué significa reabsorción tubular?","OPCION_A":"Se filtra parte de su agua y solutos hacia la cápsula glomerular.","OPCION_B":"Que el estímulo inicial del latido surge en el propio tejido cardiaco.","OPCION_C":"Que una sustancia pasa del filtrado de la nefrona de vuelta a la sangre.","OPCION_D":"Que la energía ingerida se aproxima a la energía gastada durante un período.","RESPUESTA_CORRECTA":"C","EXPLICACION":"Que una sustancia pasa del filtrado de la nefrona de vuelta a la sangre.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"923–957"},{"MATERIA":"MORFOFUNCION","TEMA":"aparato urinario","DIFICULTAD":"medio","PREGUNTA":"Si el cuerpo necesita conservar agua, ¿qué hormona aumenta su reabsorción en el riñón?","OPCION_A":"La vasopresina u hormona antidiurética, ADH.","OPCION_B":"Un estímulo mecánico; es un mecanorreceptor.","OPCION_C":"Los pulmones, al modificar la ventilación.","OPCION_D":"La mitocondria, donde ocurre gran parte de la respiración aeróbica.","RESPUESTA_CORRECTA":"A","EXPLICACION":"La vasopresina u hormona antidiurética, ADH.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"923–957"},{"MATERIA":"MORFOFUNCION","TEMA":"equilibrio hidrico y acidobasico","DIFICULTAD":"facil","PREGUNTA":"¿Dónde está la mayor parte del agua corporal: dentro o fuera de las células?","OPCION_A":"En la membrana respiratoria de los alvéolos y sus capilares.","OPCION_B":"En el bulbo raquídeo y la protuberancia del tronco encefálico.","OPCION_C":"En los túbulos seminíferos de los testículos.","OPCION_D":"Dentro de las células, en el compartimiento intracelular.","RESPUESTA_CORRECTA":"D","EXPLICACION":"Dentro de las células, en el compartimiento intracelular.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"958–980"},{"MATERIA":"MORFOFUNCION","TEMA":"equilibrio hidrico y acidobasico","DIFICULTAD":"facil","PREGUNTA":"¿Qué ion predomina en el líquido extracelular: sodio o potasio?","OPCION_A":"El sistema bicarbonato, importante para mantener el pH.","OPCION_B":"El sodio; el potasio predomina dentro de las células.","OPCION_C":"Los pulmones, al modificar la ventilación.","OPCION_D":"El hígado; la vesícula biliar la almacena y concentra.","RESPUESTA_CORRECTA":"B","EXPLICACION":"El sodio; el potasio predomina dentro de las células.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"958–980"},{"MATERIA":"MORFOFUNCION","TEMA":"equilibrio hidrico y acidobasico","DIFICULTAD":"facil","PREGUNTA":"¿Qué sistema amortiguador sanguíneo usa ácido carbónico y bicarbonato?","OPCION_A":"El sodio; el potasio predomina dentro de las células.","OPCION_B":"Los pulmones, al modificar la ventilación.","OPCION_C":"El sistema bicarbonato, importante para mantener el pH.","OPCION_D":"El encéfalo, además de sostener estructuras de la cara.","RESPUESTA_CORRECTA":"C","EXPLICACION":"El sistema bicarbonato, importante para mantener el pH.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"958–980"},{"MATERIA":"MORFOFUNCION","TEMA":"equilibrio hidrico y acidobasico","DIFICULTAD":"medio","PREGUNTA":"Si cambia la concentración de CO2, ¿qué órgano ajusta con rapidez su eliminación?","OPCION_A":"El sodio; el potasio predomina dentro de las células.","OPCION_B":"El sistema bicarbonato, importante para mantener el pH.","OPCION_C":"Un estímulo mecánico; es un mecanorreceptor.","OPCION_D":"Los pulmones, al modificar la ventilación.","RESPUESTA_CORRECTA":"D","EXPLICACION":"Los pulmones, al modificar la ventilación.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"958–980"},{"MATERIA":"MORFOFUNCION","TEMA":"aparato digestivo","DIFICULTAD":"facil","PREGUNTA":"¿Cómo se llama la onda muscular que impulsa el alimento por el tubo digestivo?","OPCION_A":"Proteasas o peptidasas.","OPCION_B":"Quimo.","OPCION_C":"Peristaltismo.","OPCION_D":"Circulación enterohepática.","RESPUESTA_CORRECTA":"C","EXPLICACION":"Peristaltismo.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"981–1027"},{"MATERIA":"MORFOFUNCION","TEMA":"aparato digestivo","DIFICULTAD":"facil","PREGUNTA":"¿Qué órgano produce bilis, útil para la digestión de grasas?","OPCION_A":"Los ácidos biliares, que participan en la emulsificación y formación de micelas.","OPCION_B":"El hígado; la vesícula biliar la almacena y concentra.","OPCION_C":"Las proteínas, que rompe en fragmentos más pequeños.","OPCION_D":"La enterocinasa de la mucosa del intestino delgado.","RESPUESTA_CORRECTA":"B","EXPLICACION":"El hígado; la vesícula biliar la almacena y concentra.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"981–1027"},{"MATERIA":"MORFOFUNCION","TEMA":"aparato digestivo","DIFICULTAD":"facil","PREGUNTA":"¿En qué segmento del tubo digestivo ocurre la mayor parte de la absorción de nutrientes?","OPCION_A":"En el íleon.","OPCION_B":"En el intestino delgado.","OPCION_C":"En el estómago, por acción de la pepsina.","OPCION_D":"En los canalículos biliares.","RESPUESTA_CORRECTA":"B","EXPLICACION":"En el intestino delgado.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"981–1027"},{"MATERIA":"MORFOFUNCION","TEMA":"aparato digestivo","DIFICULTAD":"facil","PREGUNTA":"¿Qué secreción del estómago ayuda a activar la pepsina y dificulta la supervivencia de microorganismos?","OPCION_A":"La histamina.","OPCION_B":"El ácido clorhídrico.","OPCION_C":"El esfínter esofágico inferior.","OPCION_D":"La lipasa pancreática.","RESPUESTA_CORRECTA":"B","EXPLICACION":"El ácido clorhídrico.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"981–1027"},{"MATERIA":"MORFOFUNCION","TEMA":"nutricion y metabolismo","DIFICULTAD":"facil","PREGUNTA":"¿Qué molécula usa la célula como fuente inmediata de energía para muchos trabajos?","OPCION_A":"Las proteínas de la dieta.","OPCION_B":"El ADN.","OPCION_C":"La base.","OPCION_D":"El ATP.","RESPUESTA_CORRECTA":"D","EXPLICACION":"El ATP.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"1028–1061"},{"MATERIA":"MORFOFUNCION","TEMA":"nutricion y metabolismo","DIFICULTAD":"facil","PREGUNTA":"¿Qué nutriente aporta aminoácidos para fabricar proteínas corporales?","OPCION_A":"El ATP.","OPCION_B":"Las proteínas, que rompe en fragmentos más pequeños.","OPCION_C":"Las proteínas de la dieta.","OPCION_D":"Los neumocitos de tipo II.","RESPUESTA_CORRECTA":"C","EXPLICACION":"Las proteínas de la dieta.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"1028–1061"},{"MATERIA":"MORFOFUNCION","TEMA":"nutricion y metabolismo","DIFICULTAD":"facil","PREGUNTA":"¿Qué ocurre en la glucólisis antes de entrar al ciclo de Krebs?","OPCION_A":"Las proteínas de la dieta.","OPCION_B":"Que la energía ingerida se aproxima a la energía gastada durante un período.","OPCION_C":"La glucosa se transforma en piruvato y se obtiene una pequeña cantidad de ATP.","OPCION_D":"La auricular; luego la señal atraviesa el sistema AV y excita los ventrículos.","RESPUESTA_CORRECTA":"C","EXPLICACION":"La glucosa se transforma en piruvato y se obtiene una pequeña cantidad de ATP.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"1028–1061"},{"MATERIA":"MORFOFUNCION","TEMA":"nutricion y metabolismo","DIFICULTAD":"facil","PREGUNTA":"¿Qué significa estar en equilibrio energético?","OPCION_A":"Que la sangre del tronco pulmonar vuelva al ventrículo derecho.","OPCION_B":"Que la sangre de la aorta regrese al ventrículo.","OPCION_C":"Que la energía ingerida se aproxima a la energía gastada durante un período.","OPCION_D":"La glucosa se transforma en piruvato y se obtiene una pequeña cantidad de ATP.","RESPUESTA_CORRECTA":"C","EXPLICACION":"Que la energía ingerida se aproxima a la energía gastada durante un período.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"1028–1061"},{"MATERIA":"MORFOFUNCION","TEMA":"aparato reproductor masculino","DIFICULTAD":"facil","PREGUNTA":"¿Dónde se forman los espermatozoides?","OPCION_A":"En el epidídimo.","OPCION_B":"En los túbulos seminíferos de los testículos.","OPCION_C":"En los canalículos biliares.","OPCION_D":"En los capilares, por sus paredes muy delgadas.","RESPUESTA_CORRECTA":"B","EXPLICACION":"En los túbulos seminíferos de los testículos.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"1062–1091"},{"MATERIA":"MORFOFUNCION","TEMA":"aparato reproductor masculino","DIFICULTAD":"facil","PREGUNTA":"¿En qué conducto maduran y se almacenan temporalmente los espermatozoides?","OPCION_A":"En los túbulos seminíferos de los testículos.","OPCION_B":"En el íleon.","OPCION_C":"En el intestino delgado.","OPCION_D":"En el epidídimo.","RESPUESTA_CORRECTA":"D","EXPLICACION":"En el epidídimo.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"1062–1091"},{"MATERIA":"MORFOFUNCION","TEMA":"aparato reproductor masculino","DIFICULTAD":"facil","PREGUNTA":"¿Qué células testiculares producen principalmente testosterona?","OPCION_A":"Las células intersticiales o de Leydig.","OPCION_B":"Las células regenerativas o citoblastos.","OPCION_C":"Las células enteroendocrinas.","OPCION_D":"Las células principales.","RESPUESTA_CORRECTA":"A","EXPLICACION":"Las células intersticiales o de Leydig.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"1062–1091"},{"MATERIA":"MORFOFUNCION","TEMA":"aparato reproductor masculino","DIFICULTAD":"dificil","PREGUNTA":"¿Por qué la meiosis es importante para producir gametos?","OPCION_A":"Reduce a la mitad la dotación cromosómica antes de la fecundación.","OPCION_B":"Hacen turbulento su recorrido y aumentan el contacto con la mucosa.","OPCION_C":"Aumentan el área de contacto de la mucosa con el contenido intestinal.","OPCION_D":"Ayudan a aprovechar compuestos de la dieta y producen ciertas vitaminas.","RESPUESTA_CORRECTA":"A","EXPLICACION":"Reduce a la mitad la dotación cromosómica antes de la fecundación.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"1062–1091"},{"MATERIA":"MORFOFUNCION","TEMA":"aparato reproductor femenino","DIFICULTAD":"facil","PREGUNTA":"¿Qué estructura del ovario contiene al ovocito en desarrollo?","OPCION_A":"El folículo ovárico.","OPCION_B":"La progesterona.","OPCION_C":"El endometrio.","OPCION_D":"La hormona luteinizante, LH.","RESPUESTA_CORRECTA":"A","EXPLICACION":"El folículo ovárico.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"1092–1129"},{"MATERIA":"MORFOFUNCION","TEMA":"aparato reproductor femenino","DIFICULTAD":"facil","PREGUNTA":"¿Qué hormona desencadena la ovulación cuando presenta un aumento brusco?","OPCION_A":"La progesterona.","OPCION_B":"La hormona luteinizante, LH.","OPCION_C":"El folículo ovárico.","OPCION_D":"El endometrio.","RESPUESTA_CORRECTA":"B","EXPLICACION":"La hormona luteinizante, LH.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"1092–1129"},{"MATERIA":"MORFOFUNCION","TEMA":"aparato reproductor femenino","DIFICULTAD":"facil","PREGUNTA":"¿Qué tejido del útero cambia a lo largo del ciclo menstrual y se desprende en la menstruación?","OPCION_A":"La progesterona.","OPCION_B":"El folículo ovárico.","OPCION_C":"El endometrio.","OPCION_D":"La hormona luteinizante, LH.","RESPUESTA_CORRECTA":"C","EXPLICACION":"El endometrio.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"1092–1129"},{"MATERIA":"MORFOFUNCION","TEMA":"aparato reproductor femenino","DIFICULTAD":"facil","PREGUNTA":"¿Qué hormona del cuerpo lúteo ayuda a mantener preparado el endometrio tras la ovulación?","OPCION_A":"La hormona luteinizante, LH.","OPCION_B":"La progesterona.","OPCION_C":"El endometrio.","OPCION_D":"El folículo ovárico.","RESPUESTA_CORRECTA":"B","EXPLICACION":"La progesterona.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"1092–1129"},{"MATERIA":"MORFOFUNCION","TEMA":"desarrollo humano y envejecimiento","DIFICULTAD":"facil","PREGUNTA":"¿Qué se forma al unirse un espermatozoide y un ovocito?","OPCION_A":"Un cigoto, la primera célula del nuevo organismo.","OPCION_B":"La placenta.","OPCION_C":"El colédoco, que conduce bilis hacia el duodeno.","OPCION_D":"La corteza motora, que aporta control voluntario.","RESPUESTA_CORRECTA":"A","EXPLICACION":"Un cigoto, la primera célula del nuevo organismo.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"1130–1164"},{"MATERIA":"MORFOFUNCION","TEMA":"desarrollo humano y envejecimiento","DIFICULTAD":"facil","PREGUNTA":"¿Cómo se llama la fijación inicial del blastocisto al endometrio?","OPCION_A":"Ectodermo, mesodermo y endodermo.","OPCION_B":"Peristaltismo.","OPCION_C":"Osteocito.","OPCION_D":"Implantación.","RESPUESTA_CORRECTA":"D","EXPLICACION":"Implantación.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"1130–1164"},{"MATERIA":"MORFOFUNCION","TEMA":"desarrollo humano y envejecimiento","DIFICULTAD":"facil","PREGUNTA":"¿Qué órgano permite el intercambio de nutrientes, gases y desechos entre madre y feto?","OPCION_A":"Un cigoto, la primera célula del nuevo organismo.","OPCION_B":"La insulina.","OPCION_C":"El glucagón.","OPCION_D":"La placenta.","RESPUESTA_CORRECTA":"D","EXPLICACION":"La placenta.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"1130–1164"},{"MATERIA":"MORFOFUNCION","TEMA":"desarrollo humano y envejecimiento","DIFICULTAD":"facil","PREGUNTA":"¿Cuáles son las tres capas germinales que originan los tejidos del embrión?","OPCION_A":"Implantación.","OPCION_B":"Un cigoto, la primera célula del nuevo organismo.","OPCION_C":"Ectodermo, mesodermo y endodermo.","OPCION_D":"Tres: superior, medio e inferior.","RESPUESTA_CORRECTA":"C","EXPLICACION":"Ectodermo, mesodermo y endodermo.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"1130–1164"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"introduccion a la biologia celular","DIFICULTAD":"medio","PREGUNTA":"Si una célula tiene el ADN dentro de un núcleo delimitado, ¿es procariota o eucariota?","OPCION_A":"Permitieron estudiar mejor la estructura del tejido nervioso.","OPCION_B":"Su composición química, información genética y funcionamiento.","OPCION_C":"Resistencia a antibióticos o adaptación a ciertas condiciones.","OPCION_D":"Eucariota. La envoltura nuclear separa su ADN del citoplasma.","RESPUESTA_CORRECTA":"D","EXPLICACION":"Eucariota. La envoltura nuclear separa su ADN del citoplasma.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"33–53"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"introduccion a la biologia celular","DIFICULTAD":"medio","PREGUNTA":"¿Qué rasgo te ayuda a reconocer una célula procariota frente a una eucariota?","OPCION_A":"La procariota no tiene un núcleo delimitado por membrana; su material genético ocupa una región llamada nucleoide.","OPCION_B":"Una proteína mal plegada capaz de inducir el mal plegamiento de otras.","OPCION_C":"La posibilidad de observar estructuras internas con mucho más detalle.","OPCION_D":"Una pequeña molécula circular de ADN fuera del cromosoma principal.","RESPUESTA_CORRECTA":"A","EXPLICACION":"La procariota no tiene un núcleo delimitado por membrana; su material genético ocupa una región llamada nucleoide.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"33–53"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"introduccion a la biologia celular","DIFICULTAD":"dificil","PREGUNTA":"¿Por qué un prion no se clasifica como una célula?","OPCION_A":"Permitieron estudiar mejor la estructura del tejido nervioso.","OPCION_B":"Es una proteína infecciosa mal plegada, sin organización celular ni ácido nucleico propio.","OPCION_C":"Alteraciones genéticas y mecanismos de regulación que afectan el funcionamiento celular.","OPCION_D":"Realizar procesos metabólicos y reproducirse de manera autónoma dentro de su organización celular.","RESPUESTA_CORRECTA":"B","EXPLICACION":"Es una proteína infecciosa mal plegada, sin organización celular ni ácido nucleico propio.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"33–53"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"metodos y tecnicas basicas en biologia celular","DIFICULTAD":"medio","PREGUNTA":"Quieres ver la organización interna muy fina de una célula. ¿Qué microscopía elegirías?","OPCION_A":"La microscopía electrónica, porque permite distinguir detalles más pequeños que la microscopía óptica.","OPCION_B":"La reacción en cadena de la polimerasa, o PCR, amplifica una secuencia específica de ADN.","OPCION_C":"El fraccionamiento celular mediante centrifugación diferencial.","OPCION_D":"Para localizarla en las células o en el tejido mediante una técnica inmunológica, como la inmunohistoquímica.","RESPUESTA_CORRECTA":"A","EXPLICACION":"La microscopía electrónica, porque permite distinguir detalles más pequeños que la microscopía óptica.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"54–119"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"metodos y tecnicas basicas en biologia celular","DIFICULTAD":"facil","PREGUNTA":"En una muestra hay poquísimo ADN de interés. ¿Qué técnica permite multiplicar esa secuencia?","OPCION_A":"La microscopía electrónica, porque permite distinguir detalles más pequeños que la microscopía óptica.","OPCION_B":"El fraccionamiento celular mediante centrifugación diferencial.","OPCION_C":"La reacción en cadena de la polimerasa, o PCR, amplifica una secuencia específica de ADN.","OPCION_D":"Para localizarla en las células o en el tejido mediante una técnica inmunológica, como la inmunohistoquímica.","RESPUESTA_CORRECTA":"C","EXPLICACION":"La reacción en cadena de la polimerasa, o PCR, amplifica una secuencia específica de ADN.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"54–119"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"metodos y tecnicas basicas en biologia celular","DIFICULTAD":"medio","PREGUNTA":"¿Para qué sirve marcar una proteína con un anticuerpo en una muestra de tejido?","OPCION_A":"Para dirigir la síntesis de proteínas necesarias para su estructura y actividad.","OPCION_B":"Para localizarla en las células o en el tejido mediante una técnica inmunológica, como la inmunohistoquímica.","OPCION_C":"Para comprobar que las condiciones y el ADN sean adecuados antes de avanzar a la siguiente fase.","OPCION_D":"Para compensar la dosis de genes ligados al X entre células con distinto número de cromosomas X.","RESPUESTA_CORRECTA":"B","EXPLICACION":"Para localizarla en las células o en el tejido mediante una técnica inmunológica, como la inmunohistoquímica.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"54–119"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"metodos y tecnicas basicas en biologia celular","DIFICULTAD":"medio","PREGUNTA":"Si separas los componentes de una célula según su tamaño y densidad, ¿qué técnica estás usando?","OPCION_A":"La reacción en cadena de la polimerasa, o PCR, amplifica una secuencia específica de ADN.","OPCION_B":"El fraccionamiento celular mediante centrifugación diferencial.","OPCION_C":"La microscopía electrónica, porque permite distinguir detalles más pequeños que la microscopía óptica.","OPCION_D":"El procesamiento o la exportación del ARN hacia el citoplasma.","RESPUESTA_CORRECTA":"B","EXPLICACION":"El fraccionamiento celular mediante centrifugación diferencial.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"54–119"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"estructura de la membrana plasmatica","DIFICULTAD":"dificil","PREGUNTA":"¿Por qué los fosfolípidos forman una bicapa cuando están en agua?","OPCION_A":"Sus cabezas hidrófilas miran al agua y sus colas hidrófobas quedan orientadas hacia el interior de la bicapa.","OPCION_B":"Debe caber y protegerse en el núcleo, pero también abrirse para replicarse, repararse y expresarse.","OPCION_C":"Genera nuevas mutaciones entre las que pueden surgir ventajas de crecimiento o supervivencia.","OPCION_D":"Es una proteína infecciosa mal plegada, sin organización celular ni ácido nucleico propio.","RESPUESTA_CORRECTA":"A","EXPLICACION":"Sus cabezas hidrófilas miran al agua y sus colas hidrófobas quedan orientadas hacia el interior de la bicapa.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"120–166"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"estructura de la membrana plasmatica","DIFICULTAD":"facil","PREGUNTA":"¿Qué quiere decir que la membrana sigue el modelo de mosaico fluido?","OPCION_A":"Se cultiva fácilmente y permite estudiar replicación, transcripción, proteínas y división celular.","OPCION_B":"Que los lípidos y muchas proteínas se distribuyen en una bicapa dinámica, con movilidad lateral.","OPCION_C":"Que tiene dos o más poblaciones celulares con constituciones cromosómicas distintas.","OPCION_D":"Que no posee compartimentos como núcleo, mitocondrias o retículo endoplasmático.","RESPUESTA_CORRECTA":"B","EXPLICACION":"Que los lípidos y muchas proteínas se distribuyen en una bicapa dinámica, con movilidad lateral.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"120–166"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"estructura de la membrana plasmatica","DIFICULTAD":"facil","PREGUNTA":"¿Dónde encuentras el glucocáliz: mirando al citoplasma o al exterior de la célula?","OPCION_A":"En la cara externa de la membrana; está formado por cadenas de glúcidos unidas a lípidos y proteínas.","OPCION_B":"En la superficie de neuronas, entre otros sitios del sistema nervioso.","OPCION_C":"Fuera del nucléolo, antes de incorporarse al ensamblaje ribosomal.","OPCION_D":"En la fase S de la interfase.","RESPUESTA_CORRECTA":"A","EXPLICACION":"En la cara externa de la membrana; está formado por cadenas de glúcidos unidas a lípidos y proteínas.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"120–166"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"estructura de la membrana plasmatica","DIFICULTAD":"facil","PREGUNTA":"¿Qué molécula ayuda a modular la fluidez de la membrana de células animales?","OPCION_A":"La lámina nuclear, una red de proteínas llamadas láminas.","OPCION_B":"El complejo promotor de la anafase, APC/C.","OPCION_C":"Las snRNP, ribonucleoproteínas nucleares pequeñas.","OPCION_D":"El colesterol, intercalado entre los fosfolípidos.","RESPUESTA_CORRECTA":"D","EXPLICACION":"El colesterol, intercalado entre los fosfolípidos.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"120–166"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"transporte a traves de la membrana plasmatica","DIFICULTAD":"facil","PREGUNTA":"Una molécula cruza la membrana a favor de su gradiente y sin gastar ATP. ¿Qué tipo de transporte es?","OPCION_A":"Expulsa tres iones Na+ e introduce dos iones K+; mantiene gradientes importantes para la excitabilidad celular.","OPCION_B":"Transporte pasivo; puede ocurrir por difusión simple o con ayuda de un canal o transportador.","OPCION_C":"Difusión simple a través de la membrana.","OPCION_D":"Plegamiento o modificaciones postraduccionales que le den su estructura y actividad finales.","RESPUESTA_CORRECTA":"B","EXPLICACION":"Transporte pasivo; puede ocurrir por difusión simple o con ayuda de un canal o transportador.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"167–213"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"transporte a traves de la membrana plasmatica","DIFICULTAD":"facil","PREGUNTA":"¿Qué hace la bomba sodio-potasio con cada ciclo de ATP?","OPCION_A":"Expulsa tres iones Na+ e introduce dos iones K+; mantiene gradientes importantes para la excitabilidad celular.","OPCION_B":"Transporte pasivo; puede ocurrir por difusión simple o con ayuda de un canal o transportador.","OPCION_C":"Difusión simple a través de la membrana.","OPCION_D":"El activo mueve sustancias contra su gradiente y requiere energía directa o indirectamente; el pasivo sigue el gradiente.","RESPUESTA_CORRECTA":"A","EXPLICACION":"Expulsa tres iones Na+ e introduce dos iones K+; mantiene gradientes importantes para la excitabilidad celular.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"167–213"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"transporte a traves de la membrana plasmatica","DIFICULTAD":"facil","PREGUNTA":"El oxígeno atraviesa la bicapa sin un transportador. ¿Cómo se llama ese paso?","OPCION_A":"Transporte pasivo; puede ocurrir por difusión simple o con ayuda de un canal o transportador.","OPCION_B":"Expulsa tres iones Na+ e introduce dos iones K+; mantiene gradientes importantes para la excitabilidad celular.","OPCION_C":"Comportamiento maligno e invasivo.","OPCION_D":"Difusión simple a través de la membrana.","RESPUESTA_CORRECTA":"D","EXPLICACION":"Difusión simple a través de la membrana.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"167–213"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"transporte a traves de la membrana plasmatica","DIFICULTAD":"dificil","PREGUNTA":"¿Qué diferencia al transporte activo del pasivo?","OPCION_A":"El activo mueve sustancias contra su gradiente y requiere energía directa o indirectamente; el pasivo sigue el gradiente.","OPCION_B":"Expulsa tres iones Na+ e introduce dos iones K+; mantiene gradientes importantes para la excitabilidad celular.","OPCION_C":"La replicación copia el ADN para conservar el genoma; la transcripción produce ARN de genes seleccionados.","OPCION_D":"La germinal puede transmitirse por gametos; la somática queda en las células derivadas de la afectada.","RESPUESTA_CORRECTA":"A","EXPLICACION":"El activo mueve sustancias contra su gradiente y requiere energía directa o indirectamente; el pasivo sigue el gradiente.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"167–213"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"macrotransporte a traves de la membrana plasmatica","DIFICULTAD":"facil","PREGUNTA":"La célula rodea una partícula grande y la introduce. ¿Qué proceso observas?","OPCION_A":"Fagocitosis, una forma de endocitosis para incorporar partículas grandes.","OPCION_B":"Por exocitosis de vesículas sinápticas tras fusionarse con la membrana.","OPCION_C":"Porque la carga se une primero a receptores específicos de la superficie celular.","OPCION_D":"La vesícula se fusiona con la membrana plasmática y descarga su contenido por exocitosis.","RESPUESTA_CORRECTA":"A","EXPLICACION":"Fagocitosis, una forma de endocitosis para incorporar partículas grandes.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"214–255"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"macrotransporte a traves de la membrana plasmatica","DIFICULTAD":"facil","PREGUNTA":"¿Qué ocurre con la membrana cuando una vesícula libera su contenido al exterior?","OPCION_A":"La vesícula se fusiona con la membrana plasmática y descarga su contenido por exocitosis.","OPCION_B":"La quiescencia puede revertirse; la senescencia bloquea de modo duradero la proliferación.","OPCION_C":"El mensajero porta codones; el de transferencia aporta aminoácidos y reconoce esos codones.","OPCION_D":"El mensajero lleva una secuencia para traducir; el ribosómico forma parte del ribosoma.","RESPUESTA_CORRECTA":"A","EXPLICACION":"La vesícula se fusiona con la membrana plasmática y descarga su contenido por exocitosis.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"214–255"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"macrotransporte a traves de la membrana plasmatica","DIFICULTAD":"dificil","PREGUNTA":"¿Por qué la endocitosis mediada por receptor es selectiva?","OPCION_A":"Porque la célula se compromete a duplicar su material genético antes de dividirse.","OPCION_B":"Porque la síntesis de la hebra retardada no completa del todo el extremo del cromosoma.","OPCION_C":"Porque la célula sintetiza moléculas y orgánulos, crece y replica su ADN.","OPCION_D":"Porque la carga se une primero a receptores específicos de la superficie celular.","RESPUESTA_CORRECTA":"D","EXPLICACION":"Porque la carga se une primero a receptores específicos de la superficie celular.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"214–255"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"macrotransporte a traves de la membrana plasmatica","DIFICULTAD":"dificil","PREGUNTA":"En una sinapsis, ¿por qué proceso sale el neurotransmisor de la terminal presináptica?","OPCION_A":"En la superficie de neuronas, entre otros sitios del sistema nervioso.","OPCION_B":"En puntos de control como G1 y G2; una lesión también puede detener otras fases.","OPCION_C":"Por exocitosis de vesículas sinápticas tras fusionarse con la membrana.","OPCION_D":"En diferencias de la pared que producen distinta coloración con la tinción de Gram.","RESPUESTA_CORRECTA":"C","EXPLICACION":"Por exocitosis de vesículas sinápticas tras fusionarse con la membrana.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"214–255"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"especializaciones de la membrana plasmatica","DIFICULTAD":"facil","PREGUNTA":"Una célula intestinal necesita absorber más. ¿Qué estructura aumenta su superficie apical?","OPCION_A":"El desmosoma, que conecta el citoesqueleto de células vecinas.","OPCION_B":"La unión estrecha, que sella el espacio entre ellas.","OPCION_C":"Las microvellosidades aumentan la superficie disponible para la absorción.","OPCION_D":"Una señal de localización nuclear reconocida por el sistema de importación.","RESPUESTA_CORRECTA":"C","EXPLICACION":"Las microvellosidades aumentan la superficie disponible para la absorción.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"256–290"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"especializaciones de la membrana plasmatica","DIFICULTAD":"facil","PREGUNTA":"¿Qué unión evita que el material pase libremente entre dos células epiteliales vecinas?","OPCION_A":"El desmosoma, que conecta el citoesqueleto de células vecinas.","OPCION_B":"Las microvellosidades aumentan la superficie disponible para la absorción.","OPCION_C":"La unión estrecha, que sella el espacio entre ellas.","OPCION_D":"La unión de extremos no homólogos.","RESPUESTA_CORRECTA":"C","EXPLICACION":"La unión estrecha, que sella el espacio entre ellas.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"256–290"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"especializaciones de la membrana plasmatica","DIFICULTAD":"facil","PREGUNTA":"¿Qué unión aporta resistencia mecánica cuando un tejido sufre tirones?","OPCION_A":"La unión estrecha, que sella el espacio entre ellas.","OPCION_B":"Las microvellosidades aumentan la superficie disponible para la absorción.","OPCION_C":"Puede activar anoikis, una forma de apoptosis provocada por la falta de adhesión.","OPCION_D":"El desmosoma, que conecta el citoesqueleto de células vecinas.","RESPUESTA_CORRECTA":"D","EXPLICACION":"El desmosoma, que conecta el citoesqueleto de células vecinas.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"256–290"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"especializaciones de la membrana plasmatica","DIFICULTAD":"medio","PREGUNTA":"¿Qué puede pasarle a una célula que necesita anclaje si pierde contacto con la matriz extracelular?","OPCION_A":"Puede activar señales que favorecen el avance, especialmente por G1.","OPCION_B":"Puede activar o frenar la expresión de genes existentes.","OPCION_C":"Puede activar anoikis, una forma de apoptosis provocada por la falta de adhesión.","OPCION_D":"Señales que la célula recibe mediante receptores como las integrinas.","RESPUESTA_CORRECTA":"C","EXPLICACION":"Puede activar anoikis, una forma de apoptosis provocada por la falta de adhesión.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"256–290"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"nucleo y cromatina","DIFICULTAD":"facil","PREGUNTA":"¿Por dónde intercambia el núcleo moléculas con el citoplasma?","OPCION_A":"Dos cromátidas hermanas unidas en la región del centrómero.","OPCION_B":"Durante la división celular, especialmente en metafase.","OPCION_C":"A través de los complejos de poro de la envoltura nuclear.","OPCION_D":"A cuentas en un collar: nucleosomas conectados por ADN.","RESPUESTA_CORRECTA":"C","EXPLICACION":"A través de los complejos de poro de la envoltura nuclear.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"291–349"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"nucleo y cromatina","DIFICULTAD":"facil","PREGUNTA":"¿Qué proteínas sirven de soporte para empaquetar el ADN en nucleosomas?","OPCION_A":"La replicación del ADN y la transcripción de genes.","OPCION_B":"Un cebador que aporta un extremo 3'' disponible.","OPCION_C":"La hibridación fluorescente in situ, o FISH.","OPCION_D":"Las histonas; el ADN se enrolla alrededor de ellas.","RESPUESTA_CORRECTA":"D","EXPLICACION":"Las histonas; el ADN se enrolla alrededor de ellas.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"291–349"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"nucleo y cromatina","DIFICULTAD":"medio","PREGUNTA":"Si una región de cromatina está poco compactada y suele transcribirse, ¿cómo se llama?","OPCION_A":"Acrocéntrico.","OPCION_B":"Metacéntrico.","OPCION_C":"Eucromatina.","OPCION_D":"Heterocromatina.","RESPUESTA_CORRECTA":"C","EXPLICACION":"Eucromatina.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"291–349"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"nucleo y cromatina","DIFICULTAD":"facil","PREGUNTA":"Antes de dividirse, ¿qué debe hacer la célula con su ADN?","OPCION_A":"Debe caber y protegerse en el núcleo, pero también abrirse para replicarse, repararse y expresarse.","OPCION_B":"Proteínas, sobre todo histonas y también proteínas no histonas.","OPCION_C":"Permite identificar cromosomas y reconocer algunas alteraciones estructurales.","OPCION_D":"Replicarlo para que cada célula hija reciba una copia de la información genética.","RESPUESTA_CORRECTA":"D","EXPLICACION":"Replicarlo para que cada célula hija reciba una copia de la información genética.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"291–349"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"transcripcion y maduracion del arn","DIFICULTAD":"facil","PREGUNTA":"¿Qué se fabrica cuando se transcribe un gen?","OPCION_A":"La activación de la transcripción, el procesamiento y la estabilidad del ARN.","OPCION_B":"Una molécula de ARN a partir de la información contenida en el ADN.","OPCION_C":"Los intrones; los exones se unen para formar el ARN mensajero maduro.","OPCION_D":"El ADN sirve de molde, pero no se consume ni se convierte en ARN.","RESPUESTA_CORRECTA":"B","EXPLICACION":"Una molécula de ARN a partir de la información contenida en el ADN.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"350–384"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"transcripcion y maduracion del arn","DIFICULTAD":"facil","PREGUNTA":"¿Qué se retira del pre-ARN mensajero durante el corte y empalme?","OPCION_A":"La traducción, la acción de ARN reguladores y la estabilidad de la proteína.","OPCION_B":"Un ARN pequeño que puede unirse a ARN mensajeros y regular su expresión.","OPCION_C":"El mensajero lleva una secuencia para traducir; el ribosómico forma parte del ribosoma.","OPCION_D":"Los intrones; los exones se unen para formar el ARN mensajero maduro.","RESPUESTA_CORRECTA":"D","EXPLICACION":"Los intrones; los exones se unen para formar el ARN mensajero maduro.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"350–384"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"transcripcion y maduracion del arn","DIFICULTAD":"facil","PREGUNTA":"¿Qué función cumple el nucléolo en la célula?","OPCION_A":"Entre otros factores, sus secuencias, proteínas asociadas y mecanismos celulares de degradación.","OPCION_B":"Transcripción convierte ADN en ARN; traducción usa el ARN mensajero para sintetizar proteína.","OPCION_C":"Zonas cromosómicas con genes de ARN ribosómico que participan en la formación del nucléolo.","OPCION_D":"Participa en la producción de ARN ribosómico y en el ensamblaje inicial de subunidades ribosómicas.","RESPUESTA_CORRECTA":"D","EXPLICACION":"Participa en la producción de ARN ribosómico y en el ensamblaje inicial de subunidades ribosómicas.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"350–384"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"transcripcion y maduracion del arn","DIFICULTAD":"dificil","PREGUNTA":"¿Por qué el ARN mensajero debe madurar antes de salir del núcleo?","OPCION_A":"Porque aún contiene intrones y secuencias que se eliminan durante la maduración.","OPCION_B":"Porque altera la forma del ARN y puede producir una proteína distinta o no funcional.","OPCION_C":"Porque ambas determinan cuánto ARN funcional queda disponible en cada momento.","OPCION_D":"Porque necesita procesarse, entre otros pasos con corte y empalme, para poder dirigir correctamente la síntesis de proteínas.","RESPUESTA_CORRECTA":"D","EXPLICACION":"Porque necesita procesarse, entre otros pasos con corte y empalme, para poder dirigir correctamente la síntesis de proteínas.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"350–384"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"sintesis y modificacion de proteinas","DIFICULTAD":"facil","PREGUNTA":"¿Qué lee el ribosoma para ordenar los aminoácidos de una proteína?","OPCION_A":"El ARN de transferencia, cuyo anticodón reconoce el codón del ARN mensajero.","OPCION_B":"La proteína de retinoblastoma, Rb.","OPCION_C":"Los codones del ARN mensajero.","OPCION_D":"El complejo de cohesinas.","RESPUESTA_CORRECTA":"C","EXPLICACION":"Los codones del ARN mensajero.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"385–419"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"sintesis y modificacion de proteinas","DIFICULTAD":"facil","PREGUNTA":"¿Qué molécula lleva cada aminoácido hasta el ribosoma?","OPCION_A":"Los codones del ARN mensajero.","OPCION_B":"El ARN de transferencia, cuyo anticodón reconoce el codón del ARN mensajero.","OPCION_C":"El ARN contiene ribosa; el ADN, desoxirribosa.","OPCION_D":"El ARN ribosómico 18 S.","RESPUESTA_CORRECTA":"B","EXPLICACION":"El ARN de transferencia, cuyo anticodón reconoce el codón del ARN mensajero.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"385–419"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"sintesis y modificacion de proteinas","DIFICULTAD":"facil","PREGUNTA":"Una proteína ya se tradujo, pero aún no funciona bien. ¿Qué proceso puede faltarle?","OPCION_A":"Transporte pasivo; puede ocurrir por difusión simple o con ayuda de un canal o transportador.","OPCION_B":"Puede mantener la proliferación sin depender de los controles habituales del tejido.","OPCION_C":"Crecer, duplicar su material genético y repartirlo durante la división.","OPCION_D":"Plegamiento o modificaciones postraduccionales que le den su estructura y actividad finales.","RESPUESTA_CORRECTA":"D","EXPLICACION":"Plegamiento o modificaciones postraduccionales que le den su estructura y actividad finales.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"385–419"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"sintesis y modificacion de proteinas","DIFICULTAD":"facil","PREGUNTA":"¿Dónde se sintetizan las proteínas destinadas a secreción o membranas?","OPCION_A":"Fuera del nucléolo, antes de incorporarse al ensamblaje ribosomal.","OPCION_B":"En secuencias reguladoras como el promotor.","OPCION_C":"En ribosomas asociados al retículo endoplasmático rugoso.","OPCION_D":"En uno o varios orígenes de replicación.","RESPUESTA_CORRECTA":"C","EXPLICACION":"En ribosomas asociados al retículo endoplasmático rugoso.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"385–419"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"reticulo endoplasmatico golgi y lisosomas","DIFICULTAD":"medio","PREGUNTA":"Si una célula fabrica muchas proteínas para secretarlas, ¿qué organelo suele tener muy desarrollado?","OPCION_A":"Las modifica, clasifica y dirige hacia su destino.","OPCION_B":"Los factores y la ARN polimerasa acceden con más dificultad al ADN.","OPCION_C":"El ARN lleva uracilo donde la hebra codificante de ADN tiene timina.","OPCION_D":"El retículo endoplasmático rugoso, con ribosomas unidos a su superficie.","RESPUESTA_CORRECTA":"D","EXPLICACION":"El retículo endoplasmático rugoso, con ribosomas unidos a su superficie.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"420–455"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"reticulo endoplasmatico golgi y lisosomas","DIFICULTAD":"facil","PREGUNTA":"¿Qué fabrica principalmente el retículo endoplasmático liso?","OPCION_A":"Las modifica, clasifica y dirige hacia su destino.","OPCION_B":"Suele volverse menos estable y más susceptible a degradación.","OPCION_C":"Proteínas ribosómicas, formando las subunidades del ribosoma.","OPCION_D":"Lípidos, que también sirven para formar membranas celulares.","RESPUESTA_CORRECTA":"D","EXPLICACION":"Lípidos, que también sirven para formar membranas celulares.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"420–455"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"reticulo endoplasmatico golgi y lisosomas","DIFICULTAD":"facil","PREGUNTA":"¿Qué hace el aparato de Golgi con muchas proteínas que recibe del retículo?","OPCION_A":"El retículo endoplasmático rugoso, con ribosomas unidos a su superficie.","OPCION_B":"Lípidos, que también sirven para formar membranas celulares.","OPCION_C":"Las modifica, clasifica y dirige hacia su destino.","OPCION_D":"Las snRNP, ribonucleoproteínas nucleares pequeñas.","RESPUESTA_CORRECTA":"C","EXPLICACION":"Las modifica, clasifica y dirige hacia su destino.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"420–455"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"reticulo endoplasmatico golgi y lisosomas","DIFICULTAD":"facil","PREGUNTA":"¿Para qué sirven los lisosomas?","OPCION_A":"Para degradar y reciclar material mediante enzimas digestivas.","OPCION_B":"Para comprobar que las condiciones y el ADN sean adecuados antes de avanzar a la siguiente fase.","OPCION_C":"Para estudiar su número y detectar alteraciones grandes de su estructura.","OPCION_D":"Para dirigir la síntesis de proteínas necesarias para su estructura y actividad.","RESPUESTA_CORRECTA":"A","EXPLICACION":"Para degradar y reciclar material mediante enzimas digestivas.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"420–455"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"mitocondrias y peroxisomas","DIFICULTAD":"facil","PREGUNTA":"¿En qué organelo se produce gran parte del ATP mediante metabolismo oxidativo?","OPCION_A":"En dirección 5'' a 3''.","OPCION_B":"En las mitocondrias.","OPCION_C":"En la metafase.","OPCION_D":"En la fase S.","RESPUESTA_CORRECTA":"B","EXPLICACION":"En las mitocondrias.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"456–490"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"mitocondrias y peroxisomas","DIFICULTAD":"facil","PREGUNTA":"¿Cómo se llaman los pliegues de la membrana interna mitocondrial?","OPCION_A":"Crestas mitocondriales; amplían la superficie de esa membrana.","OPCION_B":"Poseen ADN propio, aunque muchas de sus proteínas se codifican en el núcleo.","OPCION_C":"Elimina un freno normal del crecimiento o de la supervivencia celular.","OPCION_D":"A través de complejos de poro nuclear, asociado a proteínas de transporte.","RESPUESTA_CORRECTA":"A","EXPLICACION":"Crestas mitocondriales; amplían la superficie de esa membrana.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"456–490"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"mitocondrias y peroxisomas","DIFICULTAD":"facil","PREGUNTA":"¿Qué particularidad genética tienen las mitocondrias?","OPCION_A":"Crestas mitocondriales; amplían la superficie de esa membrana.","OPCION_B":"El peroxisoma, que contiene enzimas como la catalasa.","OPCION_C":"Modificar el microambiente y favorecer el desarrollo de células neoplásicas.","OPCION_D":"Poseen ADN propio, aunque muchas de sus proteínas se codifican en el núcleo.","RESPUESTA_CORRECTA":"D","EXPLICACION":"Poseen ADN propio, aunque muchas de sus proteínas se codifican en el núcleo.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"456–490"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"mitocondrias y peroxisomas","DIFICULTAD":"facil","PREGUNTA":"¿Qué organelo participa en reacciones oxidativas y en la degradación del peróxido de hidrógeno?","OPCION_A":"Poseen ADN propio, aunque muchas de sus proteínas se codifican en el núcleo.","OPCION_B":"La célula crece y se prepara para entrar en la fase S.","OPCION_C":"El peroxisoma, que contiene enzimas como la catalasa.","OPCION_D":"Un anillo de actina y miosina en la zona ecuatorial.","RESPUESTA_CORRECTA":"C","EXPLICACION":"El peroxisoma, que contiene enzimas como la catalasa.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"456–490"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"citoesqueleto","DIFICULTAD":"facil","PREGUNTA":"¿Cuáles son las tres grandes piezas del citoesqueleto?","OPCION_A":"Sitios del ADN donde empieza la apertura de la doble hélice para copiarla.","OPCION_B":"Segmentos cortos que se sintetizan de forma discontinua en la hebra retardada.","OPCION_C":"Crecer, duplicar su material genético y repartirlo durante la división.","OPCION_D":"Microtúbulos, microfilamentos de actina y filamentos intermedios.","RESPUESTA_CORRECTA":"D","EXPLICACION":"Microtúbulos, microfilamentos de actina y filamentos intermedios.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"491–535"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"citoesqueleto","DIFICULTAD":"facil","PREGUNTA":"Una vesícula se desplaza por una vía de tubulina. ¿Qué estructura le sirve de riel?","OPCION_A":"La actina.","OPCION_B":"Un microtúbulo.","OPCION_C":"Los filamentos intermedios.","OPCION_D":"La telofase.","RESPUESTA_CORRECTA":"B","EXPLICACION":"Un microtúbulo.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"491–535"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"citoesqueleto","DIFICULTAD":"facil","PREGUNTA":"¿Qué proteína forma los microfilamentos implicados en movimiento y forma celular?","OPCION_A":"Los filamentos intermedios.","OPCION_B":"Un microtúbulo.","OPCION_C":"La segurina.","OPCION_D":"La actina.","RESPUESTA_CORRECTA":"D","EXPLICACION":"La actina.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"491–535"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"citoesqueleto","DIFICULTAD":"facil","PREGUNTA":"¿Qué componente del citoesqueleto destaca por dar resistencia mecánica a la célula?","OPCION_A":"La actina.","OPCION_B":"Un microtúbulo.","OPCION_C":"El peptidoglucano.","OPCION_D":"Los filamentos intermedios.","RESPUESTA_CORRECTA":"D","EXPLICACION":"Los filamentos intermedios.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"491–535"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"senalizacion celular","DIFICULTAD":"facil","PREGUNTA":"Una célula libera una señal que actúa sobre sus vecinas. ¿Cómo se llama esa comunicación?","OPCION_A":"Señalización endocrina.","OPCION_B":"Transmite y puede amplificar la señal iniciada cuando un mensajero externo se une a su receptor.","OPCION_C":"G0 o quiescencia reversible.","OPCION_D":"Señalización paracrina.","RESPUESTA_CORRECTA":"D","EXPLICACION":"Señalización paracrina.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"536–579"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"senalizacion celular","DIFICULTAD":"facil","PREGUNTA":"Una hormona viaja por la sangre hasta un tejido distante. ¿Qué tipo de señalización es?","OPCION_A":"Señalización paracrina.","OPCION_B":"Señalización endocrina.","OPCION_C":"Transmite y puede amplificar la señal iniciada cuando un mensajero externo se une a su receptor.","OPCION_D":"G0 o quiescencia reversible.","RESPUESTA_CORRECTA":"B","EXPLICACION":"Señalización endocrina.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"536–579"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"senalizacion celular","DIFICULTAD":"dificil","PREGUNTA":"¿Por qué una célula responde a una señal y otra quizá no?","OPCION_A":"Porque la respuesta depende, entre otras cosas, de que tenga el receptor adecuado para reconocer esa señal.","OPCION_B":"Porque la célula puede superar su capacidad de adaptación y sufrir lesiones irreversibles.","OPCION_C":"Porque la síntesis de la hebra retardada no completa del todo el extremo del cromosoma.","OPCION_D":"Porque la célula se compromete a duplicar su material genético antes de dividirse.","RESPUESTA_CORRECTA":"A","EXPLICACION":"Porque la respuesta depende, entre otras cosas, de que tenga el receptor adecuado para reconocer esa señal.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"536–579"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"senalizacion celular","DIFICULTAD":"facil","PREGUNTA":"¿Qué hace un segundo mensajero dentro de la célula?","OPCION_A":"Señalización endocrina.","OPCION_B":"Transmite y puede amplificar la señal iniciada cuando un mensajero externo se une a su receptor.","OPCION_C":"Señalización paracrina.","OPCION_D":"Entre otros factores, sus secuencias, proteínas asociadas y mecanismos celulares de degradación.","RESPUESTA_CORRECTA":"B","EXPLICACION":"Transmite y puede amplificar la señal iniciada cuando un mensajero externo se une a su receptor.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"536–579"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"ciclo celular","DIFICULTAD":"facil","PREGUNTA":"¿En qué fase del ciclo celular se duplica el ADN?","OPCION_A":"En la metafase.","OPCION_B":"En el paso de G2 a la fase M.","OPCION_C":"En la fase S de la interfase.","OPCION_D":"En puntos de control como G1 y G2; una lesión también puede detener otras fases.","RESPUESTA_CORRECTA":"C","EXPLICACION":"En la fase S de la interfase.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"580–617"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"ciclo celular","DIFICULTAD":"facil","PREGUNTA":"¿Qué sucede en G1 antes de que la célula copie su ADN?","OPCION_A":"La célula podría seguir dividiéndose con alteraciones genéticas.","OPCION_B":"La célula podría dividirse antes de alcanzar un tamaño adecuado.","OPCION_C":"La célula crece y se prepara para entrar en la fase S.","OPCION_D":"La célula puede mantener señales de avance que deberían apagarse.","RESPUESTA_CORRECTA":"C","EXPLICACION":"La célula crece y se prepara para entrar en la fase S.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"580–617"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"ciclo celular","DIFICULTAD":"facil","PREGUNTA":"¿Para qué sirven los puntos de control del ciclo celular?","OPCION_A":"Porque la célula puede superar su capacidad de adaptación y sufrir lesiones irreversibles.","OPCION_B":"Para comprobar que las condiciones y el ADN sean adecuados antes de avanzar a la siguiente fase.","OPCION_C":"Porque suele estar quiescente, pero sus células pueden volver a dividirse tras un estímulo adecuado.","OPCION_D":"Porque su bloqueo proliferativo es estable, a diferencia de G0 reversible.","RESPUESTA_CORRECTA":"B","EXPLICACION":"Para comprobar que las condiciones y el ADN sean adecuados antes de avanzar a la siguiente fase.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"580–617"}]'::jsonb) AS p("MATERIA" text, "TEMA" text, "DIFICULTAD" text, "PREGUNTA" text, "OPCION_A" text, "OPCION_B" text, "OPCION_C" text, "OPCION_D" text, "RESPUESTA_CORRECTA" text, "EXPLICACION" text, "FUENTE" text, "PAGINAS_PDF" text)
), missing AS (
  SELECT p.* FROM payload p
  WHERE NOT EXISTS (
    SELECT 1 FROM public.banco_preguntas b
    WHERE b."MATERIA" = p."MATERIA" AND lower(b."PREGUNTA") = lower(p."PREGUNTA")
  )
), numbered AS (
  SELECT (SELECT coalesce(max(id), 0) FROM public.banco_preguntas) + row_number() OVER (ORDER BY "MATERIA", "TEMA", "PREGUNTA") AS id, m.*
  FROM missing m
)
INSERT INTO public.banco_preguntas (id, "MATERIA", "TEMA", "DIFICULTAD", "PREGUNTA", "OPCION_A", "OPCION_B", "OPCION_C", "OPCION_D", "RESPUESTA_CORRECTA", "EXPLICACION", "FUENTE", "PAGINAS_PDF")
SELECT n.id, n."MATERIA", n."TEMA", n."DIFICULTAD", n."PREGUNTA", n."OPCION_A", n."OPCION_B", n."OPCION_C", n."OPCION_D", n."RESPUESTA_CORRECTA", n."EXPLICACION", n."FUENTE", n."PAGINAS_PDF" FROM numbered n;
COMMIT;
